    -- CF_CURRENT_PORT_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_CURRENT_PORT_NAMEFormula RETURN VARCHAR2 IS
    V_PORT_NAME    VARCHAR2(100);
    V_PORT_INTL_CD VARCHAR2(100);
    begin
      SELECT PORT_NAME,PORT_INTL_CD INTO V_PORT_NAME, V_PORT_INTL_CD FROM SD_PORTS
      WHERE 
      PORT_CD = g_p_curr_port_cd;

      RETURN(V_PORT_NAME||'  '||V_PORT_INTL_CD);
      EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);  
    end;

    -- CF_IVR_NBRFormula بالحرف من الـ RDF
    FUNCTION CF_IVR_NBRFormula (P_PORT_CD21 NUMBER, P_DCLTN_ISN2 NUMBER) RETURN NUMBER IS
    	V_RET	NUMBER;
    begin
    	V_RET := IVR.ENCODE_IVR_NBR(P_PORT_CD21,P_DCLTN_ISN2);
    	IF V_RET > 0 THEN
    		RETURN(V_RET);
    	ELSE
    		RETURN(NULL);
    	END IF;

    end;

    -- CF_DCLTN_DT_GFormula بالحرف من الـ RDF
    FUNCTION CF_DCLTN_DT_GFormula (P_DCLTN_DT DATE) RETURN VARCHAR2 IS
    	V_G_DATE DATE;
    begin
    	V_G_DATE := HIJDATE_DB.TO_GREG(P_DCLTN_DT);
      RETURN(TO_CHAR(V_G_DATE ,'DD-MM-RRRR'));
    end;

    -- CF_PORT_TYPEFormula بالحرف من الـ RDF
    FUNCTION CF_PORT_TYPEFormula RETURN VARCHAR2 IS
    begin

      IF g_cg_p_p_port_type    = 0 THEN 	 
    	 RETURN('جهة جمركية');			
    	ELSIF g_cg_p_p_port_type = 1 THEN
    	 RETURN('بحري');	
    	ELSIF g_cg_p_p_port_type = 2 THEN 
    	 RETURN('سكة حديد');			
    	ELSIF g_cg_p_p_port_type = 3 THEN 	 
    	 RETURN('بري');
    	ELSIF g_cg_p_p_port_type = 4 THEN
       RETURN('جوي');
      ELSIF g_cg_p_p_port_type = 5 THEN 	 
    	 RETURN('مكتب بريد');			
      END IF; 
    end;

