    -- CF_driver_nameFormula بالحرف من الـ RDF
    FUNCTION CF_driver_nameFormula (P_VHT_PSPRT_NO VARCHAR2, P_VHT_PSPRT_ISSUE_DATE DATE, P_VHT_DRIVER_CTRY_CD NUMBER, P_VHT_DOC_TYPE NUMBER) RETURN VARCHAR2 IS
    v_DRIVER_NAME VARCHAR2(100);
    begin
    SELECT 
    	VD.DRIVER_NAME DRIVER_NAME INTO V_DRIVER_NAME
    FROM 
     VHCL_DRIVERS VD

    WHERE VD.PSPRT_NO           = P_VHT_PSPRT_NO
    AND   VD.PSPRT_ISSUE_DATE   = P_VHT_PSPRT_ISSUE_DATE
    AND   VD.CTRY_CD            = P_VHT_DRIVER_CTRY_CD
    AND   VD.DOC_TYPE           = P_VHT_DOC_TYPE
    ;
    RETURN(V_DRIVER_NAME);
    EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);

    end;

