    -- CF_H_TARIFFFormula بالحرف من الـ RDF
    FUNCTION CF_H_TARIFFFormula (P_FINAL_TARIFF_CD VARCHAR2, P_ANAL_ITEM_CODE_1 VARCHAR2, P_ANAL_ITEM_CODE_2 VARCHAR2) RETURN VARCHAR2 IS
    begin
      RETURN(P_FINAL_TARIFF_CD||P_ANAL_ITEM_CODE_1||P_ANAL_ITEM_CODE_2);
    end;

    -- CHK_TARIF_INST_GROUP بالحرف من الـ RDF
    --CHK_TARIF_INST_GROUP
    --DESCRIPTION	: TO CHECK IF TARIFF IS INSIDE CERTAIN GROUP OF TARIFF INSTURCTIONS OR NOT
    --PROGRAMMER	: SHERIF TAHA SHARF HASHIM
    --PROGRAMMER	: MOHAMED ABD EL_MONEM MOHAMED
    --VERSION	  	: 2.0
    --DATE 	    	: 08-06-2005
    -- 0 ===> FALSE [TARIFF NOT EXIST IN GROUP]
    -- 1 ===> TRUE  [TARIFF EXIST IN GROUP]
    -- 2 ===> FALSE [TARIFF NOT EXIST IN GROUP]
    FUNCTION CHK_TARIF_INST_GROUP (V_HARMONIZED_TARIFF VARCHAR2,V_DCLTN_DT DATE,V_GROUP_ID NUMBER) RETURN INTEGER IS
    		V_COUNT				NUMBER;
    		V_TEST_DATE 	DATE := NVL(V_DCLTN_DT,HIJDATE_DB.CUR_HIJ_DATE);
    		V_EXPRY_DATE 	DATE;
    BEGIN
    	  BEGIN
    	  SELECT MAX(EXPRY_DATE) INTO V_EXPRY_DATE
    	  FROM 	tariff_instructions
    	  WHERE INST_TYPE     = V_GROUP_ID
    	  ;
    		EXCEPTION WHEN NO_DATA_FOUND THEN 
    		V_EXPRY_DATE := NULL;
    		END;

    		IF V_EXPRY_DATE IS NULL THEN 
    			RETURN 2;
    		ELSIF V_EXPRY_DATE  < V_TEST_DATE THEN 
    			RETURN 2;
    		END IF;	

    	  SELECT COUNT(*)
    	  INTO V_COUNT
    	  FROM harmonized_tariff HT,
    	       group_items gro,
    	       tariff_groups tar,
    	       group_instructions ginst,
    	       tariff_instructions tar_inst
    	  WHERE ((HT.hrmnzd_code            = gro.hrmnzd_code)
    	        AND (tar.grp_code           = gro.grp_code)
    	        AND (tar.grp_code           = ginst.grp_code)
    	        AND (tar_inst.inst_code     = ginst.inst_code)
    					AND (HT.HRMNZD_CODE         = V_HARMONIZED_TARIFF)
    					AND (tar_inst.DECREE_STATUS = 1)
    					AND (V_TEST_DATE            <= tar_inst.expry_date)
    					AND (tar_inst.INST_TYPE     = V_GROUP_ID)
    	       );
    	   IF  V_COUNT >0 THEN
    	   		RETURN 1;
    	   ELSE
    	   		RETURN 0;
    	   END IF;
    END;

    -- CF_NEW_ITEM_DESCFormula بالحرف من الـ RDF
    FUNCTION CF_NEW_ITEM_DESCFormula (P_FINAL_TARIFF_CD VARCHAR2, P_DCLTN_DT DATE, P_ITEM_DESC VARCHAR2) RETURN VARCHAR2 IS
    	V_LENGTH  							NUMBER;
    	SUB 		  							VARCHAR2(50);
    	V_FINA_TARIF_DESC 			VARCHAR2(100);			
    	V_ITEM_DESC							VARCHAR2(1000);
    	V_NEW_ITEM_DESC					VARCHAR2(1000);	
    	V_CHK_TARIF_INST_GROUP 	NUMBER;
    BEGIN

    	V_CHK_TARIF_INST_GROUP := CHK_TARIF_INST_GROUP(P_FINAL_TARIFF_CD,P_DCLTN_DT,11);

    	IF V_CHK_TARIF_INST_GROUP IN (1,2) THEN
    		V_ITEM_DESC := P_ITEM_DESC;

    	ELSIF V_CHK_TARIF_INST_GROUP = 0 THEN
    		 BEGIN
    		 SELECT ITEM_ARBC_DESC INTO V_ITEM_DESC FROM HARMONIZED_TARIFF
    		 WHERE  HRMNZD_CODE	= P_FINAL_TARIFF_CD
    		 ;
    		 EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
    		 END;
    	END IF;	

    	V_LENGTH := LENGTH(V_ITEM_DESC);
    	IF V_LENGTH > 60 THEN
    				FOR NUM IN 1..60 LOOP
    					SUB := SUBSTR(V_ITEM_DESC, NUM, 1);
    					IF ASCII(SUB)  = 32 THEN
    						V_NEW_ITEM_DESC := SUBSTR(V_ITEM_DESC, 1, NUM);
    					END IF;
    				END LOOP;

    				IF V_CHK_TARIF_INST_GROUP = 1 THEN
    					 	V_NEW_ITEM_DESC :=  'غيرها-'||V_NEW_ITEM_DESC;
    				ELSIF V_CHK_TARIF_INST_GROUP = 0 THEN
    						V_NEW_ITEM_DESC :=  V_NEW_ITEM_DESC;
    			  END IF;

    	ELSE

    			IF V_CHK_TARIF_INST_GROUP = 1 THEN
    				 V_NEW_ITEM_DESC := 'غيرها-'||V_ITEM_DESC;
    				ELSIF V_CHK_TARIF_INST_GROUP = 0 THEN
    				 V_NEW_ITEM_DESC :=  V_ITEM_DESC;
    		  END IF;
    	END IF;		
      return (V_NEW_ITEM_DESC);
    END;

    -- CF_2Formula بالحرف من الـ RDF
    FUNCTION CF_2Formula (P_CF_H_TARIFF VARCHAR2, P_DCLTN_ISN1 NUMBER, P_ITEM_ISN NUMBER, P_ANAL_ITEM_CODE_1 VARCHAR2, P_ANAL_ITEM_CODE_2 VARCHAR2, P_FINAL_TARIFF_CD VARCHAR2, P_CF_NEW_ITEM_DESC VARCHAR2) RETURN VARCHAR2 IS
    	V_DESC VARCHAR2(1000);
    begin
    		IF P_CF_H_TARIFF='240220000000' THEN

    		SELECT T.ITEM_DESC INTO V_DESC
    FROM DECLARATIONS D , DCLTN_ITEMS I, DCLTN_ITEM_SUB_HRMNZ H, TARIFF_TAX_PRICES T
    WHERE D.PORT_CD = I.PORT_CD AND D.DCLTN_ISN = I.DCLTN_ISN
       AND I.PORT_CD = H.PORT_CD AND I.ITEM_ISN = H.ITEM_ISN
       AND H.HRMNZD_CODE = T.HTHRMNZD_CODE AND H.TAX_SEQ = T.TAX_SEQ
       AND D.DCLTN_ISN = P_DCLTN_ISN1 AND I.ITEM_ISN = P_ITEM_ISN
       AND I.FINAL_TARIFF_CD = '240220000000';
       RETURN(V_DESC);

    	ELSE

      IF P_ANAL_ITEM_CODE_1 IS NOT NULL AND P_ANAL_ITEM_CODE_2 IS NOT NULL THEN
         SELECT PEP.ITEM_DESCRIPTION
      	   INTO V_DESC
      	   FROM PETR_EXP_PRICES PEP
      	  WHERE PEP.HRMNZD_CODE = P_FINAL_TARIFF_CD
      	    AND PEP.EFF_DATE    = (SELECT MAX(EFF_DATE) 
      	    												 FROM PETR_EXP_PRICES PEP1 
      	    												WHERE PEP1.HRMNZD_CODE = PEP.HRMNZD_CODE 
      	    												  AND PEP1.ANAL_ITEM_CODE_1 = PEP.ANAL_ITEM_CODE_1
      	    												  AND PEP1.ANAL_ITEM_CODE_2 = PEP.ANAL_ITEM_CODE_2)
      	    AND PEP.ANAL_ITEM_CODE_1 = P_ANAL_ITEM_CODE_1
      	    AND PEP.ANAL_ITEM_CODE_2 = P_ANAL_ITEM_CODE_2;

      	  RETURN(V_DESC);

      ELSE
      	RETURN(P_CF_NEW_ITEM_DESC);
      END IF;
      END IF;
    EXCEPTION
    	WHEN OTHERS THEN
    		RETURN(P_CF_NEW_ITEM_DESC);  	
    end;

    -- CF_RATEFormula بالحرف من الـ RDF
    FUNCTION CF_RATEFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER, P_L_CUR_CURCY_CD NUMBER) RETURN NUMBER IS
    V_CALCN_DT    DATE;
    V_CURCY_RATE  NUMBER;

    begin
     SELECT CALCN_DT INTO V_CALCN_DT FROM COLL_ORDERS 
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND    COLL_ORDR_DT    = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD;

     SELECT CURCY_RT INTO V_CURCY_RATE FROM CURRENCY_EXCHANGES
     WHERE  CURCY_CD   = P_L_CUR_CURCY_CD
     AND    CHNG_DT    = (SELECT MAX(CHNG_DT)FROM CURRENCY_EXCHANGES
                           WHERE  CURCY_CD      = P_L_CUR_CURCY_CD
                           AND    CHNG_DT       <= P_DCLTN_DT
                           AND    CURCY_STATUS  = 1);

    RETURN(V_CURCY_RATE);  
    EXCEPTION WHEN NO_DATA_FOUND THEN
    	RETURN(NULL);
    end;

    -- V_DUTY بالحرف من الـ RDF
    FUNCTION V_DUTY (V_OLD_DUTY IN NUMBER, P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER, P_FINAL_CTRY_CD NUMBER, P_FINAL_TARIFF_CD VARCHAR2) RETURN NUMBER IS
    V_SEASON_RATE NUMBER;
    V_DUTY_RATE   NUMBER;
    V_ADD_RATE    NUMBER;
    V_SUB_RATE    NUMBER;
    V_CALCN_DT    DATE;
    V_CALCN_G_DT  DATE;
    v_msg varchar2(2000);
    BEGIN

    	BEGIN
      	SELECT CALCN_DT INTO V_CALCN_DT FROM COLL_ORDERS
      	WHERE  PORT_CD          = g_p_curr_port_cd
      	AND  	 COLL_ORDR_NBR    = P_DCLTN_NBR
      	AND 	 COLL_ORDR_DT     = P_DCLTN_DT
      	AND 	 COLL_ORDR_CTGRY  = P_DCLTN_TYPE_CD;

         V_CALCN_G_DT := HIJDATE_DB.TO_GREG (V_CALCN_DT);
      	EXCEPTION
    		WHEN NO_DATA_FOUND THEN RETURN(NULL);
    	END;

    IF ((P_FINAL_CTRY_CD = 100 AND P_DCLTN_TYPE_CD IN (1, 2)) OR P_DCLTN_TYPE_CD IN (3, 4 ,5, 6)) THEN

    BEGIN
    								SELECT 	TRF_SESN_RATE
    							INTO 		V_SEASON_RATE
    							FROM 		AGRICAL_SEASONS
    							WHERE 	HRMNZD_CODE = P_FINAL_TARIFF_CD
    							AND 		V_CALCN_G_DT BETWEEN SESN_STRT_DATE AND SESN_END_DATE;

    							IF V_SEASON_RATE IS NOT NULL THEN
    							  	V_DUTY_RATE := V_SEASON_RATE;
    							END IF;

    							EXCEPTION WHEN NO_DATA_FOUND THEN V_DUTY_RATE := V_OLD_DUTY;    
    			END
    							;
    			/*				
             V_SEASON_RATE :=LIB_USR.DUTY.GET_DUTY_RATE (:FINAL_TARIFF_CD,V_CALCN_G_DT,:CTRY_CD,1);
             IF V_SEASON_RATE <> -1
             THEN
                	V_DUTY_RATE := V_SEASON_RATE;
             ELSE
             	V_DUTY_RATE := V_OLD_DUTY;
             END IF;
    */
    ELSE-- -----------------------------------------------------------------------------------------------------------------
    			BEGIN
    							SELECT NVL(SUM(INST_DUTY_RATE),0)
    							INTO  V_ADD_RATE
    							FROM  TARIFF_INSTRUCTIONS
    							WHERE TO_CHAR(EFF_DATE, 'YYYY-MM-MI')   <= TO_CHAR(V_CALCN_DT, 'YYYY-MM-MI')
    							AND   TO_CHAR(EXPRY_DATE, 'YYYY-MM-MI') >= TO_CHAR(V_CALCN_DT, 'YYYY-MM-MI')
    							AND   INST_CODE IN (SELECT INST_CODE FROM GROUP_INSTRUCTIONS
    						        							WHERE GRP_CODE IN (SELECT GRP_CODE FROM GROUP_ITEMS WHERE HRMNZD_CODE = P_FINAL_TARIFF_CD)
    				    											AND   INST_CODE IN (4,5));
    			END;
    			IF V_ADD_RATE = 0 THEN
    					BEGIN
    									SELECT NVL(SUM(INST_DUTY_RATE),0)
    									INTO  V_SUB_RATE
    									FROM  TARIFF_INSTRUCTIONS
    									WHERE TO_CHAR(EFF_DATE, 'YYYY-MM-MI')   <= TO_CHAR(V_CALCN_DT, 'YYYY-MM-MI')
    									AND   TO_CHAR(EXPRY_DATE, 'YYYY-MM-MI') >= TO_CHAR(V_CALCN_DT, 'YYYY-MM-MI')
    									AND   INST_CODE IN (SELECT INST_CODE FROM GROUP_INSTRUCTIONS
    								        							WHERE GRP_CODE IN (SELECT GRP_CODE FROM GROUP_ITEMS WHERE HRMNZD_CODE = P_FINAL_TARIFF_CD)
    					    		  									AND   INST_CODE IN (2,3));
    		     	END;
    			ELSE
    					V_SUB_RATE := 0;
    			END IF;    		

    	  	V_DUTY_RATE := V_OLD_DUTY + V_ADD_RATE- V_SUB_RATE;

    	END IF;
    	RETURN(V_DUTY_RATE);

    end;

    -- CF_D_RATEFormula بالحرف من الـ RDF
    FUNCTION CF_D_RATEFormula (P_FINAL_TARIFF_CD VARCHAR2, P_FINAL_TARIFF_DT DATE, P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER, P_CTRY_CD NUMBER, P_FINAL_CTRY_CD NUMBER) RETURN VARCHAR2 IS
    V_DUTY_UNIT      NUMBER;
    V_DUTY_UNIT_NAME VARCHAR2(100);
    V_DUTY_RATE      NUMBER;
    V_DUTY_RATE_CD   VARCHAR2(1);
    V_DUTY_RATE_NAME VARCHAR2(20);
    V_DUTY_TYPE      NUMBER;
    V_CALCN_DT       DATE;
    V_NEW_DUTY  		NUMBER;
    V_CALCN_G_DT    DATE;
    V_CTR_CO        NUMBER; 
    v_msg varchar2(2000);
    v_new_rate     NUMBER;
    begin

    	SELECT 
    	 DUTY_UNIT              
    	,DUTY_RATE
    	,DUTY_RATE_CODE
    	,DUTY_TYPE 
    	INTO
      V_DUTY_UNIT   	
    	,V_DUTY_RATE                        
      ,V_DUTY_RATE_CD
    	,V_DUTY_TYPE   
      FROM 
      TARIFF_DETAILS
      WHERE HRMNZD_CODE = P_FINAL_TARIFF_CD
      AND   EFF_DATE    = P_FINAL_TARIFF_DT;
    	BEGIN
      	SELECT CALCN_DT INTO V_CALCN_DT FROM COLL_ORDERS
      	WHERE  PORT_CD          = g_p_curr_port_cd
      	AND  	 COLL_ORDR_NBR    = P_DCLTN_NBR
      	AND 	 COLL_ORDR_DT     = P_DCLTN_DT
      	AND 	 COLL_ORDR_CTGRY  = P_DCLTN_TYPE_CD;

        V_CALCN_G_DT := HIJDATE_DB.TO_GREG (V_CALCN_DT);

      	EXCEPTION
    		WHEN NO_DATA_FOUND THEN RETURN(NULL);
    	END;

      BEGIN
      	V_CTR_CO := 0;
    		SELECT COUNT(*) INTO V_CTR_CO
    		  FROM AGRICAL_SEASONS, CTRY_GROUP_HEADERS, CTRY_GROUP_DETAILS
    		 WHERE (    (CTRY_GROUP_HEADERS.CTRY_GRP_NBR    = CTRY_GROUP_DETAILS.CTRY_GRP_NBR)
    		        AND (CTRY_GROUP_HEADERS.CTRY_GRP_NBR    = AGRICAL_SEASONS.CTRY_GRP_NBR)
    		        AND (CTRY_GROUP_HEADERS.CTRY_GRP_STATUS = 1)
    		        AND (CTRY_GROUP_DETAILS.CTRY_GRP_STAT   = 1)
    		        AND (CTRY_GROUP_DETAILS.CTRY_CD         = P_CTRY_CD)
    		        AND (AGRICAL_SEASONS.HRMNZD_CODE        =  P_FINAL_TARIFF_CD)
    		        AND (V_CALCN_G_DT BETWEEN SESN_STRT_DATE AND SESN_END_DATE)
    		       );

      IF V_CTR_CO = 0 THEN
    		SELECT TRF_SESN_RATE
    		INTO   V_DUTY_RATE 
    		FROM   AGRICAL_SEASONS
    		WHERE  HRMNZD_CODE = P_FINAL_TARIFF_CD
    		  AND  V_CALCN_G_DT BETWEEN SESN_STRT_DATE AND SESN_END_DATE;
    	  V_DUTY_RATE_CD := 2;	  
     	END IF;	

      	EXCEPTION
    		WHEN NO_DATA_FOUND THEN NULL;
      	END;
      /*	

             v_new_rate :=LIB_USR.DUTY.GET_DUTY_RATE (:FINAL_TARIFF_CD,V_CALCN_G_DT,:CTRY_CD,1);
             IF v_new_rate <> -1
             THEN
                v_duty_rate := v_new_rate;
             END IF;
    */
      IF  V_DUTY_RATE_CD IN (3,4) THEN
      	RETURN(NULL);

      ELSIF V_DUTY_TYPE = 1 THEN
      	SELECT RV_MEANING INTO V_DUTY_RATE_NAME FROM CG_REF_CODES
      	WHERE  RV_DOMAIN    = 'DUTY_RATE_CODE'
      	  AND  RV_LOW_VALUE  = V_DUTY_RATE_CD;

        V_NEW_DUTY := V_DUTY(V_DUTY_RATE, P_DCLTN_NBR, P_DCLTN_DT, P_DCLTN_TYPE_CD, P_FINAL_CTRY_CD, P_FINAL_TARIFF_CD);  	
      	RETURN(V_NEW_DUTY||' '||V_DUTY_RATE_NAME);

        ELSIF V_DUTY_TYPE = 2 THEN  	
        	IF V_DUTY_RATE_CD   = 1 THEN
        		 V_DUTY_RATE_NAME := 'هـ';
      	 	ELSIF V_DUTY_RATE_CD   = 5 THEN	 
      			 V_DUTY_RATE_NAME := 'ر';
      		END IF;

      	SELECT MSR_UNIT_SHRT INTO V_DUTY_UNIT_NAME FROM MEASURE_UNITS
      	WHERE MSR_UNIT      = V_DUTY_UNIT;

      --	RETURN(V_DUTY_UNIT_NAME ||'/'||V_DUTY_RATE_NAME||' '||V_DUTY_RATE);
        V_NEW_DUTY := V_DUTY(V_DUTY_RATE, P_DCLTN_NBR, P_DCLTN_DT, P_DCLTN_TYPE_CD, P_FINAL_CTRY_CD, P_FINAL_TARIFF_CD);
      	RETURN(V_NEW_DUTY||' '||V_DUTY_RATE_NAME||'/'||V_DUTY_UNIT_NAME);

      END IF;	

    end;

    -- CF_DUTY_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_DUTY_NAMEFormula (P_INCOME_TYPE NUMBER) RETURN VARCHAR2 IS
    V_DUTY_TYPE VARCHAR2(100);
    BEGIN

    IF P_INCOME_TYPE = 1 THEN
    		 RETURN('قطعي'); 
    	ELSIF P_INCOME_TYPE = 2 THEN		 
    		 RETURN('م.قديم'); 
      ELSIF P_INCOME_TYPE = 3 THEN		 
    		 RETURN('معفى ك'); 
    	ELSIF P_INCOME_TYPE IN (4,15,16,17,18,19) THEN		 
    		 RETURN('م.أعفى'); 
    	ELSIF P_INCOME_TYPE IN (5,20,21,22,23,24) THEN		 
    		 RETURN('م.أ.صرف'); 
    	ELSIF P_INCOME_TYPE = 6 THEN		 
    		 RETURN('م.سندي'); 
    	ELSIF P_INCOME_TYPE = 7 THEN		 
    		 RETURN('متلف'); 
    	ELSIF P_INCOME_TYPE = 8 THEN		 
    		 RETURN('معاد'); 
    	ELSIF P_INCOME_TYPE = 9 THEN		 
    		 RETURN('معفي ت'); 
    	ELSIF P_INCOME_TYPE = 10 THEN		 
    		 RETURN('م.إعفاء'); 
    	ELSIF P_INCOME_TYPE = 11 THEN		 
         RETURN('م.دروباك'); 
    	ELSIF P_INCOME_TYPE = 12 THEN		 
    		 RETURN('م.مؤقت'); 
    	ELSIF P_INCOME_TYPE = 13 THEN		 
    		 RETURN('م.خلاف'); 
    	ELSIF P_INCOME_TYPE = 14 THEN		 
    		 RETURN('م.أخرى'); 
    	ELSIF P_INCOME_TYPE = 25 THEN		 
    		 RETURN('معفي ج'); 
    	ELSIF P_INCOME_TYPE = 26 THEN		 
    		 RETURN('محجوز'); 
    	ELSIF P_INCOME_TYPE = 27 THEN
    		 RETURN('م.ج.آخر'); 

    END IF;  

    END;

    -- CF_ITEM_TOTAL_DUTYFormula بالحرف من الـ RDF
    FUNCTION CF_ITEM_TOTAL_DUTYFormula (P_ORGNL_DUTY NUMBER, P_EXMTD_DUTY NUMBER) RETURN NUMBER IS
    begin

      RETURN(NVL(P_ORGNL_DUTY,0) - NVL(P_EXMTD_DUTY,0));
    end;

