    	  WHERE  PORT_CD 		= :P_CURR_PORT_CD 
    	  AND		 DCLTN_ISN 	= :CG$P_P_DCLTN_ISN
    	  ;

    		EXCEPTION WHEN NO_DATA_FOUND THEN RETURN('');
    END;		
    		IF V_TEMP_ITEM = 1 THEN 
    */
    		IF P_TEMP_ITEM = 1 THEN 
    			RETURN('مؤقت');
    	 ELSE
    	 	  RETURN('');
    	 END IF;
    END IF;
    end;

    -- CF_TRF_UNITFormula بالحرف من الـ RDF
    FUNCTION CF_TRF_UNITFormula (P_FINAL_TARIFF_CD VARCHAR2, P_FINAL_TARIFF_DT DATE) RETURN VARCHAR2 IS
    V_DUTY_UNIT      NUMBER;
    V_DUTY_UNIT_NAME VARCHAR2(100);
    V_DUTY_RATE_CD   VARCHAR2(1);
    V_DUTY_RATE_NAME VARCHAR2(20);
    V_DUTY_TYPE      NUMBER;
    begin

    	SELECT 
    	 DUTY_UNIT              
    	,DUTY_RATE_CODE
    	,DUTY_TYPE 
    	INTO
       V_DUTY_UNIT   	
      ,V_DUTY_RATE_CD
    	,V_DUTY_TYPE   
      FROM 
      TARIFF_DETAILS
      WHERE HRMNZD_CODE = P_FINAL_TARIFF_CD
      AND   EFF_DATE    = P_FINAL_TARIFF_DT;

      IF V_DUTY_TYPE = 2 AND V_DUTY_RATE_CD NOT IN (3,4) THEN  	

      	SELECT MSR_ARBC_NAME INTO V_DUTY_UNIT_NAME FROM MEASURE_UNITS
      	WHERE  MSR_UNIT      = V_DUTY_UNIT;

      	RETURN(V_DUTY_UNIT_NAME);
      ELSE
          	RETURN(NULL);  	
      END IF;	

    end;

    -- CF_RES_TYPE_MEANFormula بالحرف من الـ RDF
    FUNCTION CF_RES_TYPE_MEANFormula (P_RES_TYPE NUMBER, P_RELEASE_REF NUMBER) RETURN VARCHAR2 IS
    begin
      IF P_RES_TYPE = 1 THEN
      	RETURN(P_RELEASE_REF||' داخلي');
      ELSE
      	  	RETURN(P_RELEASE_REF||' خارجي');
      END IF;
    end;

    -- CF_EXMTN_DECREESFormula بالحرف من الـ RDF
    FUNCTION CF_EXMTN_DECREESFormula (P_EXMTN_DECREE_PORT_CD NUMBER, P_EXMTN_DECREE_ISN NUMBER) RETURN VARCHAR2 IS
    V_DECREE_NBR NUMBER;
    V_DECREE_SUB1 VARCHAR2(5);
    V_DECREE_SUB2 VARCHAR2(5);
    begin
     IF P_EXMTN_DECREE_PORT_CD <> 99 THEN
      SELECT DECREE_NBR,DECREE_SUB1,DECREE_SUB2 INTO V_DECREE_NBR,V_DECREE_SUB1,V_DECREE_SUB2 FROM EXMTN_DECREES
      WHERE  DECREE_PORT_CD = P_EXMTN_DECREE_PORT_CD
      AND    DECREE_ISN     = P_EXMTN_DECREE_ISN
      ;
     ELSE
      SELECT DECREE_NBR,DECREE_SUB1,DECREE_SUB2 INTO V_DECREE_NBR,V_DECREE_SUB1,V_DECREE_SUB2 FROM HQ_EXMTN_DECREES
      WHERE  DECREE_PORT_CD = P_EXMTN_DECREE_PORT_CD
      AND    DECREE_ISN     = P_EXMTN_DECREE_ISN
      ;

     END IF;

      RETURN(V_DECREE_NBR||' '||V_DECREE_SUB1||' '||V_DECREE_SUB2);
      EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);
    end;

    -- CF_ITM_TYPE_MEANFormula بالحرف من الـ RDF
    FUNCTION CF_ITM_TYPE_MEANFormula (P_ITEM_TYPE_CD NUMBER) RETURN VARCHAR2 IS
    V_ITEM_TYPE_NAME VARCHAR2(70);
    begin

    	SELECT ITEM_TYPE_NAME INTO V_ITEM_TYPE_NAME
    	FROM WVR_TYPES
      WHERE ITEM_TYPE_CD=P_ITEM_TYPE_CD;
      RETURN(V_ITEM_TYPE_NAME);

    	EXCEPTION WHEN NO_DATA_FOUND THEN
    	RETURN(NULL);
    end;

    -- CF_OLD_IMPRTD_DCLTNFormula بالحرف من الـ RDF
    FUNCTION CF_OLD_IMPRTD_DCLTNFormula (P_DCLTN_TYPE_CD NUMBER, P_IMPORT_DCLTN_ISN NUMBER) RETURN VARCHAR2 IS
    	V_OLD_DCLTN VARCHAR2(300) := NULL;
    begin
    	IF P_DCLTN_TYPE_CD = 4 THEN
    	  IF P_IMPORT_DCLTN_ISN IS NOT NULL THEN
      		SELECT 'البيان الجمركي المطلوب استعادة رسومه '||CHR(13)||CHR(10)||'الرقم :  '||DCLTN_NBR||'     التاريخ :  '||TO_CHAR(DCLTN_DT,'MI-MM-RRRR')
      	 	  INTO V_OLD_DCLTN
      	    FROM DECLARATIONS WHERE DCLTN_ISN = P_IMPORT_DCLTN_ISN;
    	  ELSE
    	  	V_OLD_DCLTN := 'لم يتم طلب استعادة الرسوم'||CHR(13)||CHR(10)||'للأصناف المعاد تصديرها';
      	END IF;
      END IF;
      RETURN(V_OLD_DCLTN);
    end;

    -- CF_GRP_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_GRP_NAMEFormula (P_DCLTN_ISN2 NUMBER, P_PMT_METHOD NUMBER, P_DCLTN_TYPE_CD NUMBER, P_GROUP_ID NUMBER) RETURN VARCHAR2 IS
    V_USER_NAME VARCHAR2(40);
    V_MGR_G_NAME VARCHAR2(50);

     CURSOR CR IS
       SELECT SC_USERS.USR_ANAME USR_NAME
       FROM   ( SELECT * FROM ACTIVITY_TRANSACTIONS WHERE ACTVY_SUB_ID = g_p_curr_port_cd  ||'!'||P_DCLTN_ISN2 )DEC_ACT, SC_USERS
       WHERE SYSOBJ_ID        = 21 
       AND SUBJ_CODE        = 1 
    	 AND ( ACTVY_TYPE=DECODE(P_PMT_METHOD,1,17,2,17,3,19,19) OR  ACTVY_TYPE=DECODE(P_PMT_METHOD,1,29,19) )
    	 AND SC_USERS.USER_ID = DEC_ACT.USER_ID
    	 ORDER BY ACTVY_ISN DESC;

     CURSOR EXPORT IS
       SELECT SC_USERS.USR_ANAME FROM
    		( SELECT * FROM ACTIVITY_TRANSACTIONS WHERE ACTVY_SUB_ID = g_p_curr_port_cd  ||'!'||P_DCLTN_ISN2) DEC_ACT, SC_USERS
    		  WHERE SYSOBJ_ID = 21 
    		  AND SUBJ_CODE 	= 1 
    		  AND ACTVY_TYPE IN (32,58)
    		  AND SC_USERS.USER_ID = DEC_ACT.USER_ID
    		  ORDER BY ACTVY_ISN DESC;

    begin
    	IF P_DCLTN_TYPE_CD IN (1,2) AND GNRL.GET_CUSTOMS_SETTING('INSP_TRAN_BANK',21)   ='N' AND 
    		 GNRL.GET_CUSTOMS_SETTING('PAY_WITHOUT_PRINT',999)='1' THEN
    		 	BEGIN
    				OPEN  CR;
    		 		FETCH CR INTO V_MGR_G_NAME;
    		 		CLOSE CR;

      	 		RETURN(V_MGR_G_NAME);
      		END;
    	ELSIF P_DCLTN_TYPE_CD IN (3,4,5,6) AND GNRL.GET_CUSTOMS_SETTING('PAY_WITHOUT_PRINT',999)='1' THEN 
    		 BEGIN
    				OPEN  EXPORT;
    		 		FETCH EXPORT INTO V_MGR_G_NAME;
    		 		CLOSE EXPORT;

      	 		RETURN(V_MGR_G_NAME);
      	END;
      ELSE
      	BEGIN
      		SELECT USR_ANAME INTO V_MGR_G_NAME FROM SC_USERS
      		WHERE  PORT_CD = g_p_curr_port_cd
      		AND    USER_ID  = (SELECT MGR_ID FROM DCLTN_GRPS 
          		               WHERE  PORT_CD = g_p_curr_port_cd
                        			 AND  GRP_ID  = P_GROUP_ID
                               AND  GRP_STATUS = 1);
      		RETURN(V_MGR_G_NAME);
      		EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);                      
      	END;
    	END IF;

    end;-- END OF MAIN BEGIN

    -- CF_BRKR_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_BRKR_NAMEFormula (P_LIC_CATEGORY NUMBER, P_DCLTN_DT DATE, P_CHANGE_CATG_DATE DATE, P_TRADE_NAME VARCHAR2, P_BRKR_NAME VARCHAR2) RETURN VARCHAR2 IS
    begin
       IF     P_LIC_CATEGORY NOT IN (1, 2)
         AND (P_DCLTN_DT >= P_CHANGE_CATG_DATE OR P_CHANGE_CATG_DATE IS NULL)
       THEN
          RETURN P_TRADE_NAME;
       ELSE
          RETURN P_BRKR_NAME;
       END IF;
    end;

    -- CF_JORDANIAN_CARSFormula بالحرف من الـ RDF
    FUNCTION CF_JORDANIAN_CARSFormula RETURN VARCHAR2 IS

    	V_AMT							NUMBER;

      CURSOR PLATE_CTRY_CD (V_TRAN_SEQ NUMBER,V_TRANS_DATE_H DATE) IS
      SELECT PLATE_CTRY_CD PLATE_CTRY_CD
      FROM   VHCL_TRANSACTIONS
      WHERE	 PORT_CD   			= g_p_curr_port_cd
      AND		 TRANS_DATE_H 	= V_TRANS_DATE_H
      AND    TRAN_SEQ				= V_TRAN_SEQ
      ;

      CURSOR DCLTN_GATE IS
      SELECT VHCL_TRANS_NBR,VHCL_TRANS_DATE
      FROM   DCLTN_GATE_TRANS
      WHERE  PORT_CD   = g_p_curr_port_cd
      AND		 DCLTN_ISN = g_cg_p_p_dcltn_isn
      and    dgt_type <> 7;

    BEGIN

    FOR J IN DCLTN_GATE LOOP
     FOR C IN PLATE_CTRY_CD(J.VHCL_TRANS_NBR,J.VHCL_TRANS_DATE) LOOP

    	IF C.PLATE_CTRY_CD = 112 THEN
    		 SELECT AMT INTO V_AMT FROM DCLTN_ADDNL_FEES
    		 WHERE  PORT_CD 	= g_p_curr_port_cd
    		 AND    DCLTN_ISN = g_cg_p_p_dcltn_isn
    		 AND 		ACCT_SEQ	= 9
     		 ;
    	END IF;

    	END LOOP;
    END LOOP;
    	IF V_AMT IS NOT NULL THEN
    		RETURN(' رسوم معاملة بالمثل'||'('||' رسم مساعي + رسم طوابع'||')'||' '||CHR(13) || CHR(10)|| V_AMT ||' ريال تدفع من قبل السائق ');
    	ELSE
    		RETURN(NULL);
    	END IF;	
    	EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);	
    END;

    -- CF_ITEM_COUNTFormula بالحرف من الـ RDF
    FUNCTION CF_ITEM_COUNTFormula (P_CS_ITEM_COUNT NUMBER, P_INV_TYPE NUMBER) RETURN VARCHAR2 IS
    V_ITEM_SEQ NUMBER;
    begin     
    	V_ITEM_SEQ := MOD(P_CS_ITEM_COUNT, 5);
    	IF P_INV_TYPE IS NOT NULL THEN
      IF V_ITEM_SEQ = 1 THEN
      	RETURN (' أ'||'-');
      ELSIF V_ITEM_SEQ = 2 THEN
      	RETURN ('ب-');
      ELSIF V_ITEM_SEQ = 3 THEN
      	RETURN ('جـ-');
      ELSIF V_ITEM_SEQ = 4 THEN
      	RETURN ('د -');
      ELSIF V_ITEM_SEQ = 0 THEN
      	RETURN ('هـ-');
      END IF;
      ELSE
      	RETURN(NULL);
      	END IF;
    end;

    -- CF_INV_TYPEFormula بالحرف من الـ RDF
    FUNCTION CF_INV_TYPEFormula (P_INV_TYPE NUMBER) RETURN VARCHAR2 IS
    V_INV_TYPE VARCHAR2(100);
    begin
      SELECT RV_MEANING INTO V_INV_TYPE FROM CG_REF_CODES
      WHERE  RV_DOMAIN    ='INV_TYPE'
      AND    RV_LOW_VALUE = P_INV_TYPE;

      RETURN(V_INV_TYPE);
    EXCEPTION WHEN NO_DATA_FOUND THEN
    	RETURN(NULL);
    END;

    -- CF_INV_PMNT_MTHOD_MEANFormula بالحرف من الـ RDF
    FUNCTION CF_INV_PMNT_MTHOD_MEANFormula (P_INV_PMT_METHOD NUMBER) RETURN VARCHAR2 IS
    	V_DESC VARCHAR2(150);
    begin
      SELECT RV_MEANING INTO V_DESC FROM CG_REF_CODES WHERE RV_DOMAIN = 'INV_PMT_METHOD' AND RV_LOW_VALUE = P_INV_PMT_METHOD;
      RETURN(V_DESC );
    EXCEPTION
    	WHEN OTHERS THEN
    		RETURN(NULL);
    end;

    -- CF_LIC_TYPEFormula بالحرف من الـ RDF
    FUNCTION CF_LIC_TYPEFormula (P_LIC_TYPE NUMBER, P_LIC_NBR NUMBER) RETURN VARCHAR2 IS
    V_LIC_TYPE VARCHAR2(100);
    begin

    	IF P_LIC_TYPE IS NOT NULL AND P_LIC_NBR IS NOT NULL THEN
      SELECT RV_MEANING INTO V_LIC_TYPE FROM CG_REF_CODES
      WHERE  RV_DOMAIN    ='LICENSE TYPE'
      AND    RV_LOW_VALUE = P_LIC_TYPE;

      RETURN(V_LIC_TYPE);
    	ELSE
    	RETURN (NULL);
    	END IF;	
      --EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);
    END;

    -- CF_EXIT_PORT_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_EXIT_PORT_NAMEFormula (P_EXIT_PORT_CD NUMBER) RETURN VARCHAR2 IS
    V_PORT_NAME VARCHAR2(100);
    begin
      SELECT PORT_NAME INTO V_PORT_NAME FROM SD_PORTS
      WHERE 
      PORT_CD = P_EXIT_PORT_CD;

      RETURN(V_PORT_NAME);
      EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);  
    end;

    -- CF_TOTAL_DUTYFormula بالحرف من الـ RDF
    FUNCTION CF_TOTAL_DUTYFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_TOTAL_DUTY      NUMBER(15,2);
     V_CHECK_INS_REQ       NUMBER;
     V_SUM_TOTAL_DUTY_INSU NUMBER(15,2);
     V_SUM_TOTAL           NUMBER(15,2);
    begin
    BEGIN	
      SELECT INS_REQ_PMT INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

     IF V_CHECK_INS_REQ = 1 THEN

      SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOTAL_DUTY_INSU 
      FROM COLL_ORDER_DTLS COD,ACCT_ITEM_DTLS AID
      WHERE  PORT_CD         = g_p_curr_port_cd
      AND    COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT     = P_DCLTN_DT
      AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND    AID.AID_TYPE    = 2
      AND    AID.ACCT_ISN    = 8
      AND    AID.ACCT_SEQ    = COD.ACCT_SEQ
      ;

    ELSE
    	V_SUM_TOTAL_DUTY_INSU := 0;
    END IF;	

     EXCEPTION WHEN NO_DATA_FOUND THEN

      SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOTAL_DUTY_INSU 
      FROM COLL_ORDER_DTLS COD,ACCT_ITEM_DTLS AID
      WHERE  PORT_CD         = g_p_curr_port_cd
      AND    COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT     = P_DCLTN_DT
      AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND    AID.AID_TYPE    = 2
      AND    AID.ACCT_ISN    = 8
      AND    AID.ACCT_SEQ    = COD.ACCT_SEQ;

     END;

     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOTAL_DUTY 
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND   COLL_ORDR_DT     = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    COD.ACCT_SEQ    = 1
     ;

    V_SUM_TOTAL := V_SUM_TOTAL_DUTY_INSU + V_SUM_TOTAL_DUTY ;

    RETURN(V_SUM_TOTAL);
    end;

    -- CALL_TOTAL_VATFormula بالحرف من الـ RDF
    FUNCTION CALL_TOTAL_VATFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_VAT NUMBER(15,2);
    begin

       SELECT NVL(SUM(AMT+nvl(SRCE_PORT_AMT,0)),0) INTO  V_SUM_VAT
     FROM COLL_ORDER_DTLS COD
     WHERE    PORT_CD          = g_p_curr_port_cd
     AND      COLL_ORDR_NBR    = P_DCLTN_NBR
     AND    COLL_ORDR_DT       = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY    = P_DCLTN_TYPE_CD
     AND    COD.ACCT_SEQ       IN (90,91)
     ;

    RETURN (V_SUM_VAT);

    end;

    -- CALL_TOTAL_EXCISEFormula بالحرف من الـ RDF
    FUNCTION CALL_TOTAL_EXCISEFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_EXISE NUMBER(15,2);
     BEGIN
     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO  V_SUM_EXISE
     FROM COLL_ORDER_DTLS COD
     WHERE    PORT_CD          = g_p_curr_port_cd
     AND      COLL_ORDR_NBR    = P_DCLTN_NBR
     AND    COLL_ORDR_DT       = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY    = P_DCLTN_TYPE_CD
     AND    COD.ACCT_SEQ       IN (86,87,187,92,93,94)
     ;

    RETURN (V_SUM_EXISE);

    end;

    -- CF_HANDLINGFormula بالحرف من الـ RDF
    FUNCTION CF_HANDLINGFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_HANDLING NUMBER(15,2);
    begin

     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_HANDLING 
     FROM COLL_ORDER_DTLS COD
     WHERE    PORT_CD          = g_p_curr_port_cd
     AND      COLL_ORDR_NBR    = P_DCLTN_NBR
     AND    COLL_ORDR_DT       = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY    = P_DCLTN_TYPE_CD
     AND    COD.ACCT_SEQ       IN (10,32)
     ;

    RETURN(V_SUM_HANDLING);

    end;

    -- CF_STORAGEFormula بالحرف من الـ RDF
    FUNCTION CF_STORAGEFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_STORAGE NUMBER(15,2);
     V_CHECK_INS_REQ       NUMBER;
     V_SUM_STORAGE_INSU    NUMBER(15,2);
     V_SUM_TOTAL           NUMBER(15,2);
    begin
      SELECT COUNT(*) INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD       = g_p_curr_port_cd
      AND COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT  = P_DCLTN_DT
      AND COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND INS_REQ_PMT     = 1;

    IF V_CHECK_INS_REQ = 1 THEN
     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_STORAGE_INSU
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND   COLL_ORDR_DT     = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    ACCT_SEQ    = 22
     ;	
    ELSE
    	V_SUM_STORAGE_INSU := 0;
    END IF;	

     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_STORAGE 
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND   COLL_ORDR_DT     = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    ACCT_SEQ    = 11
     ;

    V_SUM_TOTAL := V_SUM_STORAGE + V_SUM_STORAGE_INSU;
    RETURN(V_SUM_STORAGE);
    end;

    -- CF_TOTAL_DUTY_DEFINITFormula بالحرف من الـ RDF
    FUNCTION CF_TOTAL_DUTY_DEFINITFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_TOTAL_DUTY      NUMBER(15,2);
    begin

     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOTAL_DUTY 
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND    COLL_ORDR_DT    = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    ACCT_SEQ    = 1
     ;

    RETURN(V_SUM_TOTAL_DUTY );
    end;

    -- CF_STORAGE_DEFINITFormula بالحرف من الـ RDF
    FUNCTION CF_STORAGE_DEFINITFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_SUM_STORAGE NUMBER(15,2);
    begin
     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_STORAGE 
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND   COLL_ORDR_DT     = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    ACCT_SEQ    = 11
     ;

    RETURN(V_SUM_STORAGE);
    end;

    -- CF_TOTAL_DUTY_INSUFormula بالحرف من الـ RDF
    FUNCTION CF_TOTAL_DUTY_INSUFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
     V_CHECK_INS_REQ       NUMBER;
     V_SUM_TOTAL_DUTY_INSU NUMBER(15,2);

    begin
    BEGIN	
      SELECT INS_REQ_PMT INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

     IF V_CHECK_INS_REQ = 1 THEN

      SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOTAL_DUTY_INSU 
      FROM COLL_ORDER_DTLS COD,ACCT_ITEM_DTLS AID
      WHERE  PORT_CD         = g_p_curr_port_cd
      AND    COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT     = P_DCLTN_DT
      AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND    AID.AID_TYPE    = 2
      AND    AID.ACCT_ISN    = 8
      AND    AID.ACCT_SEQ    = COD.ACCT_SEQ
      ;

    ELSE
    	V_SUM_TOTAL_DUTY_INSU := 0;
    END IF;	

     EXCEPTION WHEN NO_DATA_FOUND THEN
    	V_SUM_TOTAL_DUTY_INSU := 0;
    END;

    RETURN(V_SUM_TOTAL_DUTY_INSU);
    END;

    -- CF_STORAGE_INSUFormula بالحرف من الـ RDF
    FUNCTION CF_STORAGE_INSUFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS

     V_CHECK_INS_REQ       NUMBER;
     V_SUM_STORAGE_INSU    NUMBER(15,2);

    begin
    BEGIN	
      SELECT INS_REQ_PMT INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

     IF V_CHECK_INS_REQ = 1 THEN

     SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_STORAGE_INSU
     FROM COLL_ORDER_DTLS COD
     WHERE  PORT_CD         = g_p_curr_port_cd
     AND    COLL_ORDR_NBR   = P_DCLTN_NBR
     AND    COLL_ORDR_DT    = P_DCLTN_DT
     AND    COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
     AND    ACCT_SEQ    = 22
     ;	
     ELSE
     V_SUM_STORAGE_INSU := 0;
     END IF;

     EXCEPTION WHEN NO_DATA_FOUND THEN
     V_SUM_STORAGE_INSU := 0;
    END; 	
    RETURN(V_SUM_STORAGE_INSU);
    END;

    -- CF_FORMULA_SUMFormula بالحرف من الـ RDF
    FUNCTION CF_FORMULA_SUMFormula (P_CF_TOTAL_FEE_DIFINIT NUMBER, P_CF_TOTAL_DUTY_DEFINIT NUMBER, P_CF_HANDLING NUMBER, P_CF_STORAGE_DEFINIT NUMBER, P_CALL_TOTAL_EXCISE NUMBER, P_CALL_TOTAL_VAT NUMBER) RETURN NUMBER IS
    begin
      RETURN(P_CF_TOTAL_FEE_DIFINIT - (P_CF_TOTAL_DUTY_DEFINIT + P_CF_HANDLING + P_CF_STORAGE_DEFINIT + P_CALL_TOTAL_EXCISE + P_CALL_TOTAL_VAT));
    end;

    -- CF_FORMULA_INSU_SUMFormula بالحرف من الـ RDF
    FUNCTION CF_FORMULA_INSU_SUMFormula (P_CF_TOTAL_FEE_INSURE NUMBER, P_CF_TOTAL_DUTY_INSU NUMBER, P_CF_STORAGE_INSU NUMBER) RETURN NUMBER IS
    begin
      RETURN(P_CF_TOTAL_FEE_INSURE - (P_CF_TOTAL_DUTY_INSU + P_CF_STORAGE_INSU));
    end;

    -- CF_OTHER_CHARGESFormula بالحرف من الـ RDF
    FUNCTION CF_OTHER_CHARGESFormula (P_CF_FORMULA_SUM NUMBER, P_CF_FORMULA_INSU_SUM NUMBER) RETURN NUMBER IS
    begin
      RETURN(P_CF_FORMULA_SUM + P_CF_FORMULA_INSU_SUM);
    end;

    -- CF_TOTAL_FEE_DIFINITFormula بالحرف من الـ RDF
    FUNCTION CF_TOTAL_FEE_DIFINITFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
    V_SUM_TOT_FEE_DEF NUMBER(15,2);
    V_CHECK_INS_REQ   NUMBER;
    BEGIN	
      SELECT count(*) INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

      SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOT_FEE_DEF 
      FROM COLL_ORDER_DTLS COD
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   (COD.ACCT_SEQ IN (SELECT ACCT_SEQ FROM ACCT_ITEM_DTLS WHERE AID_TYPE = 1) OR V_CHECK_INS_REQ = 0);

    RETURN(V_SUM_TOT_FEE_DEF);
    end;

    -- CF_TOTAL_FEE_INSUREFormula بالحرف من الـ RDF
    FUNCTION CF_TOTAL_FEE_INSUREFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN NUMBER IS
    V_SUM_TOT_FEE_INSU NUMBER(15,2);
    V_CHECK_INS_REQ       NUMBER;
    begin
    BEGIN	
      SELECT INS_REQ_PMT INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

     IF V_CHECK_INS_REQ IN (1,2) THEN

      SELECT NVL(SUM(AMT+SRCE_PORT_AMT),0) INTO V_SUM_TOT_FEE_INSU 
      FROM COLL_ORDER_DTLS COD
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      AND   COD.ACCT_SEQ IN (SELECT ACCT_SEQ FROM ACCT_ITEM_DTLS WHERE AID_TYPE = 2);
    ELSE
    	V_SUM_TOT_FEE_INSU := 0;
    END IF;	

     EXCEPTION WHEN NO_DATA_FOUND THEN
    	V_SUM_TOT_FEE_INSU := 0;
    END;

    RETURN(V_SUM_TOT_FEE_INSU);
    end;

    -- CF_GET_INSUE_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_GET_INSUE_NAMEFormula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE, P_DCLTN_TYPE_CD NUMBER) RETURN VARCHAR2 IS
    V_CHECK_INS_REQ       NUMBER;

    BEGIN	

      SELECT INS_REQ_PMT INTO V_CHECK_INS_REQ FROM INS_REQS
      WHERE PORT_CD         = g_p_curr_port_cd
      AND   COLL_ORDR_NBR   = P_DCLTN_NBR
      AND   COLL_ORDR_DT    = P_DCLTN_DT
      AND   COLL_ORDR_CTGRY = P_DCLTN_TYPE_CD
      ;

    IF V_CHECK_INS_REQ = 1 THEN
    	 RETURN('تأمين نقدي');
    ELSE
    	 RETURN('خطاب ضمان');
    END IF;	

     	 exception when NO_DATA_FOUND then return('خطاب ضمان');
    END;

    -- CF_METHOD_DESCFormula بالحرف من الـ RDF
    FUNCTION CF_METHOD_DESCFormula (P_COLL_ORDR_STA1 NUMBER, P_PMT_METHOD NUMBER) RETURN VARCHAR2 IS
    V_PMT_METHOD_NAME VARCHAR2(100);
    begin
    		IF P_COLL_ORDR_STA1 = 7 THEN
    		RETURN('محصل من رصيد المخلص');
    	ELSE
    		BEGIN
    	IF P_PMT_METHOD IS NOT NULL THEN
      SELECT RV_MEANING INTO V_PMT_METHOD_NAME FROM CG_REF_CODES
      WHERE  RV_DOMAIN    ='DCLTN_PMT_METHOD'
      AND    RV_LOW_VALUE = P_PMT_METHOD ;

      RETURN(V_PMT_METHOD_NAME);
    	ELSE
    	RETURN(NULL);
    	END IF;
    	EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);
    	END;
    	END IF;
    end;

    -- CF_BANK_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_BANK_NAMEFormula (P_CO_BANK_CD NUMBER) RETURN VARCHAR2 IS
     V_BANK_NAME VARCHAR2(50);
    begin

     IF P_CO_BANK_CD IS NOT NULL THEN	
     SELECT BANK_NAME INTO V_BANK_NAME FROM BANKS
     WHERE  BANK_CD = P_CO_BANK_CD;

     RETURN(V_BANK_NAME);
     ELSE
     RETURN(NULL);	
     END IF;
     EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);

    end;

    -- CF_ATHRZ_RCPT1Formula بالحرف من الـ RDF
    FUNCTION CF_ATHRZ_RCPT1Formula (P_RCPT_TYPE22 NUMBER, P_ATM_AUTHRZTN_CD22 VARCHAR2, P_RCPT_NBR22 NUMBER) RETURN VARCHAR2 IS
    begin
      IF P_RCPT_TYPE22 = 2 THEN
      	RETURN('رقم التفويض : '||P_ATM_AUTHRZTN_CD22);
      ELSE
      	RETURN(P_RCPT_NBR22);
      END IF;
    end;

    -- CF_BANK_BRNCH_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_BANK_BRNCH_NAMEFormula (P_CO_BANK_CD NUMBER, P_CO_BANK_BRNCH_CD NUMBER) RETURN VARCHAR2 IS
     V_BANK_BRANCH_NAME VARCHAR2(50);
    begin
     IF P_CO_BANK_CD IS NOT NULL AND P_CO_BANK_BRNCH_CD IS NOT NULL THEN	
     SELECT BANK_BRNCH_NAME INTO V_BANK_BRANCH_NAME FROM BANK_BRNCHS
     WHERE  BANK_CD       = P_CO_BANK_CD
     AND    BANK_BRNCH_CD = P_CO_BANK_BRNCH_CD;

     RETURN(V_BANK_BRANCH_NAME);
     ELSE
     RETURN(NULL);
     END IF;	
     EXCEPTION WHEN NO_DATA_FOUND THEN RETURN(NULL);
    end;

    -- CF_COLL_STA_7Formula بالحرف من الـ RDF
    FUNCTION CF_COLL_STA_7Formula (P_COLL_ORDR_STA NUMBER, P_PORT_CD2 NUMBER, P_COLL_ORDR_NBR NUMBER, P_COLL_ORDR_DT DATE, P_COLL_ORDR_CTGRY NUMBER) RETURN VARCHAR2 IS
    	V_ACCT_NBR  NUMBER;
    	V_TRANS_SEQ NUMBER;
    begin
    IF P_COLL_ORDR_STA = 7 THEN
      SELECT   ACCT_NBR , max(TRANS_SEQ)
      INTO     V_ACCT_NBR, V_TRANS_SEQ
      FROM     CLIENT_PAY_ACCT_TRANS
      WHERE    PORT_CD                = P_PORT_CD2
        AND    COLL_ORDR_NBR          = P_COLL_ORDR_NBR
        AND    COLL_ORDR_DT           = P_COLL_ORDR_DT
        AND  	 COLL_ORDR_CTGRY        = P_COLL_ORDR_CTGRY
      GROUP BY ACCT_NBR;

       RETURN('رقم الحساب :  '||V_ACCT_NBR||CHR(13)||'  مسلسل العملية  :  '||V_TRANS_SEQ);
    ELSE
    	RETURN(NULL);
    END IF;
    EXCEPTION
    	WHEN OTHERS THEN
    		RETURN(NULL);

    end;

    -- CF_USER_NAMEFormula بالحرف من الـ RDF
    FUNCTION CF_USER_NAMEFormula (P_CO_BANK_CD NUMBER, P_CO_BANK_BRNCH_CD NUMBER, P_COLL_DT DATE, P_RCPT_NBR22 NUMBER, P_RCPT_TYPE22 NUMBER) RETURN VARCHAR2 IS
    V_NAME   VARCHAR2(100);
    begin
      SELECT 'المحصل/ '||USR_ANAME 
      INTO   V_NAME 
      FROM   SC_USERS
      WHERE  USER_ID IN	  (SELECT USER_ID 
      										 FROM   BANK_RCPTS 
      										 WHERE  PORT_CD				=g_p_curr_port_cd
      										   AND  BANK_CD				=P_CO_BANK_CD
      										   AND  BANK_BRNCH_CD	=P_CO_BANK_BRNCH_CD
      										   AND  REV_DT				=P_COLL_DT
      										   AND  RCPT_NBR			=P_RCPT_NBR22
      										   AND  RCPT_TYPE			=P_RCPT_TYPE22);

      RETURN(V_NAME);

    EXCEPTION
    	WHEN OTHERS THEN
    		RETURN(NULL);
    end;

    -- CF_HQ_ISDFormula بالحرف من الـ RDF
    FUNCTION CF_HQ_ISDFormula RETURN VARCHAR2 IS
    begin
      IF g_p_hq_isd = 99 THEN
      	RETURN('طباعة مركزية(مصلحة)');
      ELSIF g_p_hq_isd = 98 THEN
      	RETURN('طباعة رقابة وتدقيق');
      ELSE
      	RETURN(NULL);
      END IF;
    end;

    -- CF_HIJ_DATEFormula بالحرف من الـ RDF
    FUNCTION CF_HIJ_DATEFormula RETURN DATE IS
    V_HIJ_DATE DATE;
    V_TIME     DATE;
    begin
      V_HIJ_DATE    :=  HIJDATE_DB.Cur_Hij_Date;

      RETURN(V_HIJ_DATE);
    end;

    -- CF_1Formula بالحرف من الـ RDF
    FUNCTION CF_1Formula (P_DCLTN_NBR NUMBER, P_DCLTN_DT DATE) RETURN VARCHAR2 IS
    begin
      RETURN(' ملحق أرقام شاسيهات السيارات للبيان رقم : '||P_DCLTN_NBR
      ||' بتاريخ : '||TO_CHAR(P_DCLTN_DT,'MI-MM-RRRR'));
    end;

    -- TIN_NOFormula بالحرف من الـ RDF
    FUNCTION TIN_NOFormula (P_DCLTN_ISN2 NUMBER) RETURN VARCHAR2 IS
    V_TIN_NBR VARCHAR2(15);
    begin

       SELECT TIN_NBR INTO V_TIN_NBR FROM DCLTN_VAT_EXCISE_DATA
      WHERE PORT_CD=g_p_curr_port_cd
      AND DCLTN_STATS_ISN=P_DCLTN_ISN2;

      RETURN V_TIN_NBR;

    EXCEPTION 
    	WHEN 
    	others then return '';

    return null;

    end;

    -- FOR_INCOME_TYPE بالحرف من الـ RDF (B_10 «بيان جمركي مؤقت»)
    FUNCTION FOR_INCOME_TYPE (P_DCLTN_TYPE_CD NUMBER) RETURN BOOLEAN IS
        V_COUNT_DCLTN_ITEMS NUMBER;
        V_COUNT             NUMBER;
    BEGIN
        SELECT COUNT (*) INTO V_COUNT_DCLTN_ITEMS FROM DCLTN_ITEMS WHERE PORT_CD = g_p_curr_port_cd AND DCLTN_ISN = g_cg_p_p_dcltn_isn;

        IF P_DCLTN_TYPE_CD IN (1, 2) THEN
            IF V_COUNT_DCLTN_ITEMS > 0 THEN
                SELECT COUNT (*) INTO V_COUNT FROM DCLTN_ITEMS
                 WHERE PORT_CD = g_p_curr_port_cd AND DCLTN_ISN = g_cg_p_p_dcltn_isn AND DUTY_TYPE IN (12, 17, 22);
                RETURN V_COUNT_DCLTN_ITEMS = V_COUNT;
            ELSE
                RETURN FALSE;
            END IF;
        ELSE
            IF V_COUNT_DCLTN_ITEMS > 0 THEN
                SELECT COUNT (*) INTO V_COUNT FROM DCLTN_ITEMS
                 WHERE PORT_CD = g_p_curr_port_cd AND DCLTN_ISN = g_cg_p_p_dcltn_isn AND TEMP_ITEM = 1;
                RETURN V_COUNT_DCLTN_ITEMS = V_COUNT;
            ELSE
                RETURN FALSE;
            END IF;
        END IF;
    END FOR_INCOME_TYPE;

    FUNCTION ARD_DCLN3100 (P_PARAMETER1   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER2   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER3   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER4   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER5   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER6   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER7   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER8   IN VARCHAR2 DEFAULT NULL,
                           P_PARAMETER9   IN VARCHAR2 DEFAULT NULL)
        RETURN CLOB
    IS
        retVal                 CLOB;
        v_cg_p_p_dcltn_isn     NUMBER := TO_NUMBER (P_PARAMETER1);
        v_cg_p_p_port_type     NUMBER := TO_NUMBER (P_PARAMETER2);
        v_cg_p_p_reprint       NUMBER := TO_NUMBER (P_PARAMETER3);
        v_cg_p_p_impr_diff_clrnc NUMBER := TO_NUMBER (P_PARAMETER4);
        v_cg_p_p_prnt_cd       NUMBER := TO_NUMBER (P_PARAMETER5);
        v_p_curr_port_cd       NUMBER := TO_NUMBER (P_PARAMETER6);
        v_p_hq_isd             NUMBER := TO_NUMBER (P_PARAMETER7);
        v_p_bank_txt           VARCHAR2 (4000) := P_PARAMETER8;
        v_p_dec_ret_tit        VARCHAR2 (4000) := P_PARAMETER9;
        v_port_name            VARCHAR2 (200);   -- CF_CURRENT_PORT_NAME
        v_ivr                  NUMBER;           -- CF_IVR_NBR
        v_bar                  VARCHAR2 (200);   -- CF_BAR_CD (قبل Bar128AB)
        v_n                    NUMBER;
        v_cnt                  NUMBER;
        v_sum_duty             NUMBER;           -- CS_SUM_CF_ITEM_TOTAL_DUTY
        cs_gross_wt            NUMBER;           -- CS_GROSS_WT
        cs_item_qty            NUMBER;           -- CS_ITEM_QTY
        cs_g_p_no              NUMBER;           -- CS_g_p_no
        cs_vhcl                NUMBER;           -- CS_g_exp_vhcl_t
        cs_car                 NUMBER;           -- CS_CAR
        cs_ret_meam            VARCHAR2 (4000);  -- CS_RET_MEAM
        f_other                NUMBER;           -- CF_OTHER_CHARGES
        v_ok                   NUMBER;
        v_b5 VARCHAR2 (32767); v_b6 VARCHAR2 (32767); v_b9 VARCHAR2 (32767); v_b12 VARCHAR2 (32767); v_b15 VARCHAR2 (32767); v_b17 VARCHAR2 (32767);
        v_b18 VARCHAR2 (32767); v_b19 VARCHAR2 (32767); v_b20 VARCHAR2 (32767); v_wvr VARCHAR2 (32767); v_inv VARCHAR2 (32767); v_docs VARCHAR2 (32767);
        v_coll VARCHAR2 (32767); v_l VARCHAR2 (32767); v_rec VARCHAR2 (32767);
        v_first                BOOLEAN := TRUE;
    BEGIN
        DBMS_LOB.createtemporary (retVal, TRUE);

        -- معاملات التقرير اللي الـ formulas بتقراها
        g_p_curr_port_cd := v_p_curr_port_cd;
        g_cg_p_p_port_type := v_cg_p_p_port_type;
        g_cg_p_p_dcltn_isn := v_cg_p_p_dcltn_isn;
        g_p_hq_isd := v_p_hq_isd;
        g_cg_p_p_dcltn_isn := v_cg_p_p_dcltn_isn;
        g_p_curr_port_cd := v_p_curr_port_cd;
        v_port_name := CF_CURRENT_PORT_NAMEFormula;

        dbms_lob.append (retVal, '<head><style>
