        </tbody>
      </table>
    </div></td>
  </tr>
</tfoot>
<tbody>
  <tr>
    <td>');

        -- CG$Q_DCLTN بالحرف من الـ RDF (R_CG$G_DCLTN1): صفحة لكل بيان (التعهدات جاية من نفس الكويري)
        FOR h IN (SELECT * FROM (SELECT x.*, ROW_NUMBER () OVER (PARTITION BY PORT_CD21, DCLTN_ISN2 ORDER BY NULL) rn__ FROM (
                          SELECT
                          T1.TYPE_ID L_DCLTNT_TYPE_ID,
                          T0.DCLTN_NBR DCLTN_NBR,
                          T3.ARBC_IMPR_NAME T_IMPR_NAME,
                          T5.ARBC_IMPR_NAME AGNT_NAME,
                          T2.PORT_CD L_USR_PORT_CD,
                          T2.USER_ID L_USR_USER_ID,
                          T2.USR_ANAME INSP_NAME,
                          T3.PORT_CD L_IMP_PORT_CD2,
                          T3.IMPR_NBR L_IMP_IMPR_NBR2,
                          T4.PORT_CD L_BKM_PORT_CD,
                          T4.LIC_TYPE L_BKM_LIC_TYPE,
                          T4.LIC_NBR L_BKM_LIC_NBR,
                          T4.BRKR_NAME BRKR_NAME,
                          T4.LIC_CATEGORY,
                          T4.CHANGE_CATG_DATE,
                          T4.TRADE_NAME,
                          T5.PORT_CD L_IMP_PORT_CD,
                          T5.IMPR_NBR L_IMP_IMPR_NBR,
                          T3.BUS_ID IMPR_BUS_ID,
                          T0.PORT_CD PORT_CD21,
                          T0.REPRINT_RSN_CD,
                          T0.DCLTN_ISN DCLTN_ISN2,
                          T0.DCLTN_TYPE_CD DCLTN_TYPE_CD,
                          T0.DCLTN_DT DCLTN_DT,
                          T1.TYPE_NAME DCLTN_TYPE_NAME,
                          T0.BRKR_PORT_CD BRKR_PORT_CD,
                          T0.IMPR_NBR IMPR_NBR,
                          T0.AGENT_NBR DCLTN_AGENT_NBR,
                           T0.INSPTR_ID INSPTR_ID,
                          T0.LIC_NBR LIC_NBR,
                          T0.LIC_TYPE LIC_TYPE,
                          T3.BUS_ID_BRNCH IMPR_BUS_ID_BRNCH,
                          T5.BUS_ID EXP_BUS_ID,
                          T5.BUS_ID_BRNCH EXP_BUS_ID_BRNCH,
                          T0.PMT_METHOD PMT_METHOD,
                          T0.PRINT_CNT,
                          T0.DHL_BL,
                          T0.DHL_OWNER,
                          T0.CLRNC_DT,
                          T0.EXPORT_TO EXPORT_TO,
                          T0.FINAL_CTRY_CD FINAL_CTRY_CD,
                          T0.EXIT_PORT_CD EXIT_PORT_CD,
                          T0.CL_NBR CL_NBR,
                          T0.CL_DT CL_DT,
                          T0.CL_VAL CL_VAL,
                          T0.RSTRCD_ITEMS RSTRCD_ITEMS,
                          T0.DCLTN_STA_CD DCLTN_STATUS,
                          T6.DOC_INS_NBR,
                          T6.DOC_INS_DT,
                          T6.RCPT_NBR RCPT_NBR22,
                          T14.ATM_AUTHRZTN_CD ATM_AUTHRZTN_CD22,
                          T6.RCPT_TYPE RCPT_TYPE22,
                          T6.COLL_DT,
                          T6.BANK_CD CO_BANK_CD,
                          T6.BANK_BRNCH_CD CO_BANK_BRNCH_CD,
                          T6.COLL_ORDR_STA COLL_ORDR_STA1,
                          --T6.IVR_NBR,
                          T0.GROUP_ID GROUP_ID,
                          WI.ITEM_TYPE_CD,
                          WI.ISSUED_DT, WI. ITEM_SER_NBR,
                          W.WVR_SEQ_NBR,
                          WI.ITEM_STATUS,
                          T0.GATE_DT,
                          IMPORT_DCLTN_ISN
                          FROM
                          COLL_ORDERS T6,
                          BANK_RCPTS T14,
                          IMPORTERS T5,
                          BRKR_MSTR T4,
                          IMPORTERS T3,
                          SC_USERS T2,
                          DCLTN_TYPES T1,
                          DECLARATIONS T0,
                          WAIVERS W, WVR_ITEMS WI
                          WHERE
                          T0.DCLTN_TYPE_CD = T1.TYPE_ID AND
                          T0.PORT_CD = T2.PORT_CD (+) AND
                          T0.INSPTR_ID = T2.USER_ID (+) AND
                          T0.PORT_CD = T3.PORT_CD (+) AND
                          T0.IMPR_NBR = T3.IMPR_NBR (+) AND
                          T0.BRKR_PORT_CD = T4.PORT_CD (+) AND
                          T0.LIC_TYPE = T4.LIC_TYPE (+) AND
                          T0.LIC_NBR = T4.LIC_NBR (+) AND
                          T0.PORT_CD = T5.PORT_CD AND
                          T0.AGENT_NBR = T5.IMPR_NBR AND
                          T0.PORT_CD  =   v_p_curr_port_cd  AND
                          T0.DCLTN_ISN = v_cg_p_p_dcltn_isn AND
                          T6.PORT_CD   (+) = T0.PORT_CD AND
                          T6.COLL_ORDR_NBR (+)  = T0.DCLTN_NBR  AND
                          T6.COLL_ORDR_DT (+)     = T0.DCLTN_DT AND
                          T6.COLL_ORDR_CTGRY (+) = T0.DCLTN_TYPE_CD
                          AND
                          T6.PORT_CD = T14.PORT_CD (+) AND
                          T6.BANK_CD = T14.BANK_CD (+) AND
                          T6.BANK_BRNCH_CD = T14.BANK_BRNCH_CD (+) AND
                          T6.COLL_DT = T14.REV_DT (+) AND
                          T6.RCPT_NBR = T14.RCPT_NBR (+) AND
                          T6.RCPT_TYPE = T14.RCPT_TYPE (+)
                          AND  T0.PORT_CD  =W.WVR_PORT_CD (+)
                          AND T0.DCLTN_ISN =  W.DCLTN_ISN(+)
                          AND  WI.WVR_PORT_CD  (+) = W.WVR_PORT_CD
                            AND         WI.WVR_SEQ_NBR    (+) = W.WVR_SEQ_NBR
                            AND         WI.ISSUED_DT        (+) = W.ISSUED_DT
                                        ) x) WHERE rn__ = 1 ORDER BY PORT_CD21, DCLTN_ISN2)
        LOOP
            v_ivr := CF_IVR_NBRFormula (h.PORT_CD21, h.DCLTN_ISN2);
            -- CF_BAR_CDFormula من غير Bar128AB (الباركود بيترسم CODE_128)
            v_bar := LPAD (v_p_curr_port_cd, 3, '0') || LPAD (h.DCLTN_TYPE_CD, 2, '0') || LPAD (h.DCLTN_NBR, 6, '0') || TO_CHAR (h.DCLTN_DT, 'MIMMRR');
            f_other := CF_OTHER_CHARGESFormula (CF_FORMULA_SUMFormula (CF_TOTAL_FEE_DIFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CF_TOTAL_DUTY_DEFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CF_HANDLINGFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CF_STORAGE_DEFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CALL_TOTAL_EXCISEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CALL_TOTAL_VATFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)), CF_FORMULA_INSU_SUMFormula (CF_TOTAL_FEE_INSUREFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CF_TOTAL_DUTY_INSUFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), CF_STORAGE_INSUFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)));
            v_sum_duty := 0;

            FOR i IN (SELECT * FROM (
                          SELECT
                          T11.CURCY_CD L_CUR_CURCY_CD,
                          T7.CTRY_CD L_CTRY_CTRY_CD1,
                          T6.FINAL_TARIFF_CD FINAL_TARIFF_CD,
                          T9.INTL_MSR_UNIT L_IMU_INTL_MSR_UNIT,
                          T8.TYPE_CD L_ET_TYPE_CD,
                          T6.EXMTN_TYPE EXMTN_CD,
                          T8.TYPE_NAME EXMTN_SRCE,
                          T6.PORT_CD PORT_CD1,
                          T10.PORT_CD PORT_CD3,
                          T10.INV_ISN INV_ISN2,
                          T6.ITEM_ISN ITEM_ISN,
                          T10.INV_SEQ INV_SEQ,
                          T6.ITEM_SEQ ITEM_SEQ1,
                          T6.DCLTN_ISN DCLTN_ISN1,
                          T10.INV_NBR INV_NBR,
                          T6.INV_ISN INV_ISN,
                          T10.INV_TYPE INV_TYPE,
                          T6.CTRY_CD CTRY_CD,
                          T10.DCLTN_ISN DCLTN_ISN3,
                          T10.INV_CURCY_CD DCLTN_INV_INV_CURCY_CD,
                          T6.FINAL_TARIFF_DT FINAL_TARIFF_DT,
                          T6.ITEM_DESC ITEM_DESC,
                          T7.CTRY_INTL_CD ORIGIN,
                          T6.INV_COST INV_COST,
                          T11.CURCY_INTL_CD CURCY_INTL_CD,
                          T6.CIF_COST CIF_COST,
                          T6.DUTY_TYPE INCOME_TYPE,
                          T6.INTL_MSR_UNIT INTL_MSR_UNIT,
                          T6.INTL_QTY INTL_QTY,
                          T9.IMSR_ARBC_NAME MSR_UNIT_NAME,
                          T6.NET_WT NET_WT,
                          T6.GROSS_WT GROSS_WT,
                          T6.ORGNL_DUTY ORGNL_DUTY,
                          T6.EXMTD_DUTY EXMTD_DUTY,
                          T6.TRF_UNIT_QTY TRF_UNIT_QTY,
                          T6.INV_QTY,
                          T6.INV_MSR_UNIT,
                          T12.MSR_ARBC_NAME,
                          T6.EXMTN_DECREE_PORT_CD,
                          T6.EXMTN_DECREE_ISN,
                          T6.EXMTN_ITEM_SEQ,
                          T6.EXMTN_ITEM_SUB_SEQ,
                          T6.TEMP_ITEM,
                          T6.ANAL_ITEM_CODE_1,
                          T6.ANAL_ITEM_CODE_2,
                          T10.INV_PMT_METHOD
                          FROM
                          CURRENCIES T11,
                          DCLTN_INVOICES T10,
                          INTL_MSR_UNITS T9,
                          EXMTN_TYPES T8,
                          COUNTRIES T7,
                          DCLTN_ITEMS T6,
                          MEASURE_UNITS T12
                          WHERE
                          h.PORT_CD21 = T6.PORT_CD AND
                          h.DCLTN_ISN2 = T6.DCLTN_ISN AND
                          T6.CTRY_CD = T7.CTRY_CD AND
                          T6.EXMTN_TYPE = T8.TYPE_CD (+) AND
                          T6.INTL_MSR_UNIT = T9.INTL_MSR_UNIT AND
                          T6.INV_MSR_UNIT  = T12.MSR_UNIT AND
                          T6.PORT_CD = T10.PORT_CD (+) AND
                          T6.INV_ISN = T10.INV_ISN (+) AND
                          T10.INV_CURCY_CD = T11.CURCY_CD (+)
                          ORDER BY  INV_SEQ,ITEM_SEQ1
                             ))
            LOOP
                v_sum_duty := v_sum_duty + NVL (CF_ITEM_TOTAL_DUTYFormula (i.ORGNL_DUTY, i.EXMTD_DUTY), 0);   -- CS_SUM_CF_ITEM_TOTAL_DUTY
            END LOOP;

            -- 5 المتروكات (R_11 / G_LFTS) وأول نوع (CS_RET_MEAM)، والعناوين B_201 / B_32 لو P_DEC_RET_TIT

            v_b5 := NULL;
            cs_ret_meam := NULL;

            FOR r IN (SELECT * FROM (
                              SELECT
                              	 dcltn_items.dcltn_isn dcltn_isn_rl,
                                               dcltn_items.port_cd   port_cd_rl,
                                               dcltn_items.ret_type,
                                               ret_reps.rep_nbr,
                                                to_char(ret_reps.rep_dt,'mi-mm-rrrr') rep_dt,
                                               ret_reps.L_BILL_NBR
                                FROM    dcltn_items,
                                            ret_items,
                                          --  ret_action_items,
                                            ret_reps
                              WHERE
                                --               (ret_action_items.port_cd      = ret_reps.port_cd)
                                --      AND (ret_action_items.ret_bill_nbr = ret_reps.ret_bill_nbr)
                                              (ret_items.port_cd      = ret_reps.port_cd)
                                      AND (ret_items.ret_bill_nbr = ret_reps.ret_bill_nbr)
                               /*       AND (dcltn_items.port_cd                 = ret_action_items.port_cd)
                                      AND (dcltn_items.ract_action_nbr    = ret_action_items.action_nbr)
                                      AND (dcltn_items.ract_ret_bill_nbr    = ret_action_items.ret_bill_nbr)
                                      AND (dcltn_items.ract_ret_item_nbr  = ret_action_items.ret_item_nbr)
                                      AND (dcltn_items.ract_action_cd      = ret_action_items.action_cd)
                              */
                                      AND (dcltn_items.port_cd                 = ret_items.port_cd)
                                      AND (dcltn_items.ract_ret_bill_nbr    = ret_items.ret_bill_nbr)
                                      AND (dcltn_items.ract_ret_item_nbr  = ret_items.ret_item_nbr)
                                      AND ret_reps.STAGE_CD <> 99
                              union
                              SELECT
                                               dcltn_items.dcltn_isn dcltn_isn_rl,
                                               dcltn_items.port_cd   port_cd_rl,
                              	              dcltn_items.ret_type,
                                                lft_bills.lft_bill_nbr,
                                                to_char( lft_bills.lft_date,'mi-mm-rrrr'),
                                                TO_NUMBER(NULL) -------lft_bills.L_BILL_NBR
                                FROM   dcltn_items,
                                                lft_action_items,
                                                lft_bills
                                WHERE
                              	 (lft_action_items.port_cd       = lft_bills.port_cd)
                                      AND (lft_action_items.lft_bill_nbr   = lft_bills.lft_bill_nbr)
                                      AND (dcltn_items.port_cd                  = lft_action_items.port_cd)
                                      AND (dcltn_items.lacit_action_nbr     = lft_action_items.action_nbr)
                                      AND (dcltn_items.lacit_lft_bill_nbr      = lft_action_items.lft_bill_nbr)
                                      AND (dcltn_items.lacit_lft_item_nbr    = lft_action_items.lft_item_nbr)
                                      AND (dcltn_items.lacit_action_cd      = lft_action_items.action_cd)
                                      AND STAGE_CD <> 99
                              union
                              SELECT
                                               dcltn_items.dcltn_isn dcltn_isn_rl,
                                               dcltn_items.port_cd   port_cd_rl,
                                               dcltn_items.ret_type,
                                               lft_sale_items.auction_nbr,
                                               to_char(lft_sale_items.auction_year),
                                               TO_NUMBER(NULL)                   -------lft_bills.L_BILL_NBR
                                FROM dcltn_items,
                                              lft_bills,
                              			    lft_sale_bills ,
                              			    lft_sale_items
                                WHERE
                              	               (dcltn_items.port_cd                        = lft_sale_items.port_cd)
                                      AND (dcltn_items.lsitms_auction_nbr   = lft_sale_items.auction_nbr)
                                      AND (dcltn_items.lsitms_auction_year = lft_sale_items.auction_year)
                                      AND (dcltn_items.lsitms_lft_bill_nbr       = lft_sale_items.lft_bill_nbr)
                                      AND (dcltn_items.lsitms_lft_item_nbr    = lft_sale_items.lft_item_nbr)
                                      AND (dcltn_items.lsitms_sale_nbr         = lft_sale_items.sale_nbr)
                              		AND (    (lft_bills.port_cd                 = lft_sale_bills.port_cd)
                                      AND (lft_bills.lft_bill_nbr                  = lft_sale_bills.lft_bill_nbr)
                                      AND (lft_sale_bills.port_cd            = lft_sale_items.port_cd)
                                      AND (lft_sale_bills.auction_year = lft_sale_items.auction_year)
                                      AND (lft_sale_bills.auction_nbr    = lft_sale_items.auction_nbr)
                                      AND (lft_sale_bills.sale_nbr          = lft_sale_items.sale_nbr)
                                      AND (lft_sale_bills.lft_bill_nbr        = lft_sale_items.lft_bill_nbr)      )
                                      AND STAGE_CD <> 99
                             ) WHERE PORT_CD_RL = h.PORT_CD21 AND DCLTN_ISN_RL = h.DCLTN_ISN2 ORDER BY RET_TYPE, L_BILL_NBR)
            LOOP
                IF cs_ret_meam IS NULL THEN
                    cs_ret_meam := CF_1FORMULA0006 (r.RET_TYPE);
                END IF;

                v_b5 := v_b5 || CASE WHEN v_b5 IS NOT NULL THEN '<br/>' END
                        || APEX_ESCAPE.HTML (CF_R_L_NBRFormula (r.RET_TYPE, r.REP_NBR) || '  ' || CF_R_L_DTFormula (r.RET_TYPE, r.REP_DT) || '  ' || r.L_BILL_NBR);
            END LOOP;

            v_b5 := APEX_ESCAPE.HTML (cs_ret_meam) || CASE WHEN v_p_dec_ret_tit IS NOT NULL THEN ' <b style="color:#0e0f50;">تاريخه / رقم البوليصة</b>' END
                    || CASE WHEN v_b5 IS NOT NULL THEN '<br/>' || v_b5 END;

            -- 17 المنافيست الأجنبي / تاريخ / السائق (M_11)، والملخصات CS_GROSS_WT / CS_ITEM_QTY / CS_g_p_no من المنافيستات

            v_b17 := '<b style="color:#0e0f50;">المانفيست الأجنبي / تاريخ / السـائق</b> ';
            v_l := NULL;
            cs_gross_wt := 0;
            cs_item_qty := 0;
            cs_g_p_no := 0;

            FOR m IN (SELECT * FROM (
                              SELECT
                              DLM.DCLTN_ISN DCLTN_ISN,
                              DLM.FRGN_MAN_NO        MAN_NO,
                              DLM.FRGN_MAN_DATE    MAN_DT,
                              DLM.CTRY_CD                   CTRY_CD,
                              DLM.FR_PORT_CD            FR_PORT_CD,
                              DLM.PORT_CD                   PORT_CD,
                              DLM.DCLTN_MNFST_ISN DCLTN_MNFST_ISN
                              FROM
                              DCLTN_LAND_MNFSTS DLM
                              WHERE DLM.DCLTN_ISN               = h.DCLTN_ISN2
                              AND       DLM.PORT_CD                  = h.PORT_CD21
                             ) ORDER BY PORT_CD, DCLTN_ISN, MAN_NO, MAN_DT, CTRY_CD, FR_PORT_CD)
            LOOP
                FOR b IN (SELECT * FROM (
                              SELECT  LB.PORT_CD,
                                              LB.BILL_NBR,
                                              LB.GROSS_WT,
                                              LB.DCLTN_MNFST_ISN
                              FROM LAND_BILLS LB
                              WHERE  LB.PORT_CD                      = m.PORT_CD
                              AND        LB.DCLTN_MNFST_ISN(+) = m.DCLTN_MNFST_ISN
                                 ))
                LOOP
                    cs_gross_wt := cs_gross_wt + NVL (b.GROSS_WT, 0);   -- CS_GROSS_WT (sum GROSS_WT1 = LB.GROSS_WT);
                END LOOP;

                FOR q IN (SELECT * FROM (
                              SELECT LI.PORT_CD,
                                             LI.ITEM_QTY ITEM_QTY1 ,
                                             LI.DCLTN_MNFST_ISN
                              FROM LAND_ITEMS    LI
                              WHERE   LI.PORT_CD                      = m.PORT_CD
                              AND         LI.DCLTN_MNFST_ISN(+) = m.DCLTN_MNFST_ISN
                                 ))
                LOOP
                    cs_item_qty := cs_item_qty + NVL (q.ITEM_QTY1, 0);
                END LOOP;

                IF h.DCLTN_TYPE_CD IN (1, 2) THEN   -- M_1
                    v_b17 := v_b17 || '<br/>' || APEX_ESCAPE.HTML (m.MAN_NO || '  ' || TO_CHAR (m.MAN_DT, 'DD-MM-YYYY'));
                END IF;

                FOR t IN (SELECT * FROM (
                              SELECT
                               DLMT.TRAN_SEQ TRAN_SEQ,
                               DLMT.TRANS_DATE_H TRAN_DT,
                               DLMT.DCLTN_MNFST_ISN MNFST_ISN,
                               DLMT.PORT_CD PORT_CD
                              FROM
                              DCLTN_LAND_MNFST_TRANS DLMT
                              WHERE DLMT.DCLTN_MNFST_ISN  = m.DCLTN_MNFST_ISN
                              AND       DLMT.PORT_CD                   = m.PORT_CD
                                 ) ORDER BY PORT_CD, TRAN_SEQ, TRAN_DT)
                LOOP
                    FOR r IN (SELECT * FROM (
                              SELECT DISTINCT
                              VT.PLATE_NO PLATE_NO,
                              VT.VHCL_CHASSIS_NO CHASSIS_NO,
                              VT.TRAN_SEQ TRAN_SEQ,
                              VT.TRANS_DATE_H TRAN_DT,
                              VT.PORT_CD PORT_CD,
                              VT.PSPRT_NO                  VT_PSPRT_NO,
                              VT.PSPRT_ISSUE_DATE VT_PSPRT_ISSUE_DATE,
                              DR.DRIVER_NAME DRIVER_NAME
                              FROM
                              VHCL_TRANSACTIONS VT,VHCL_DRIVERS DR
                              WHERE  VT.TRAN_SEQ           = t.TRAN_SEQ
                              AND        VT.TRANS_DATE_H  = t.TRAN_DT
                              AND        VT.PORT_CD              = t.PORT_CD
                              AND        VT.PSPRT_NO = DR.PSPRT_NO
                              AND        VT.PSPRT_ISSUE_DATE = DR.PSPRT_ISSUE_DATE
                              AND        VT.DRIVER_CTRY_CD    =  DR.CTRY_CD
                              AND        VT.DOC_TYPE    =  DR.DOC_TYPE
                                     ) ORDER BY TRAN_SEQ, DRIVER_NAME)
                    LOOP
                        cs_g_p_no := cs_g_p_no + CASE WHEN r.CHASSIS_NO IS NOT NULL THEN 1 ELSE 0 END;

                        IF h.DCLTN_TYPE_CD IN (1, 2) THEN
                            v_b17 := v_b17 || '  ' || APEX_ESCAPE.HTML (r.DRIVER_NAME);   -- R_8
                        END IF;
                    END LOOP;
                END LOOP;
            END LOOP;

            -- سواقين ولوحات وشاسيهات البوابة (R_5 / R_6، B_2 لو CS_g_exp_vhcl_t <> 0)

            cs_vhcl := 0;
            v_l := NULL;

            FOR g IN (SELECT * FROM (
                              SELECT
                               DGT.PORT_CD PORT_CD,
                               DGT.DCLTN_ISN DCLTN_ISN,
                               DGT.VHCL_TRANS_NBR VHCL_TRANS_NBR,
                               DGT.VHCL_TRANS_DATE VHCL_TRANS_DATE
                              FROM DCLTN_GATE_TRANS DGT
                              WHERE PORT_CD      = h.PORT_CD21
                              AND       DCLTN_ISN   = h.DCLTN_ISN2
                              and    dgt_type <> 7
                             ) ORDER BY DCLTN_ISN, VHCL_TRANS_NBR, VHCL_TRANS_DATE, PORT_CD)
            LOOP
                FOR r IN (SELECT * FROM (
                              SELECT
                               VHT.PLATE_NO                   VHT_PLATE_NO,
                               VHT.VHCL_CHASSIS_NO   VHT_CHASSIS_NO,
                               VHT.PSPRT_NO                  VHT_PSPRT_NO,
                               VHT.PSPRT_ISSUE_DATE VHT_PSPRT_ISSUE_DATE,
                               VHT.TRAN_SEQ                  VHT_TRAN_SEQ,
                               VHT.TRANS_DATE_H         VHT_TRANS_DT,
                               VHT.PORT_CD                     VHT_PORT_CD,
                               VHT.DOC_TYPE                   VHT_DOC_TYPE,
                               VHT.DRIVER_CTRY_CD      VHT_DRIVER_CTRY_CD
                              FROM
                              VHCL_TRANSACTIONS VHT
                              WHERE  VHT.TRAN_SEQ               =    g.VHCL_TRANS_NBR
                              AND        VHT.TRANS_DATE_H      =    g.VHCL_TRANS_DATE
                              AND        VHT.PORT_CD                  =    g.PORT_CD
                                 ) ORDER BY VHT_PLATE_NO)
                LOOP
                    cs_vhcl := cs_vhcl + CASE WHEN r.VHT_CHASSIS_NO IS NOT NULL THEN 1 ELSE 0 END;
                    v_ok := 1;
                    IF h.DCLTN_TYPE_CD IN (1, 2) THEN
                        SELECT COUNT (*) INTO v_ok FROM DCLTN_GATE_TRANS DGT
                         WHERE DGT.VHCL_TRANS_NBR = r.VHT_TRAN_SEQ AND DGT.VHCL_TRANS_DATE = r.VHT_TRANS_DT AND DGT.PORT_CD = r.VHT_PORT_CD AND DGT.DGT_TYPE = 4;
                    END IF;

                    IF v_ok > 0 THEN
                        v_b17 := v_b17 || '<br/>' || APEX_ESCAPE.HTML (CF_driver_nameFormula (r.VHT_PSPRT_NO, r.VHT_PSPRT_ISSUE_DATE, r.VHT_DRIVER_CTRY_CD, r.VHT_DOC_TYPE));
                        v_l := v_l || CASE WHEN v_l IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.VHT_PLATE_NO || '   ' || r.VHT_CHASSIS_NO);
                    END IF;
                END LOOP;
            END LOOP;

            IF cs_vhcl <> 0 THEN
                v_b17 := v_b17 || '<br/>' || '<b style="color:#0e0f50;">رقم اللوحة / رقم الشاسيه</b> ' || '<br/>' || v_l;
            END IF;

            -- لوحات وشاسيهات المنافيست (R_16 / G_port_cd22، B_207 لو CS_g_p_no <> 0)، وشاسيهات الاستلام (M_89 لو CS_CAR <= 4، وإلا الملحق)

            v_l := NULL;
            v_rec := NULL;
            cs_car := 0;

            FOR p IN (SELECT * FROM (
                              SELECT   DISTINCT
                              DLM.DCLTN_ISN DCLTN_ISN22,
                              DLM.PORT_CD port_cd22,
                              --VT1.VHCL_CHASSIS_NO REC_CHASSIS_NO22,
                              VT.PLATE_NO PLATE_NO22,
                              VT.VHCL_CHASSIS_NO CHASSIS_NO22,
                              VT.TRAN_SEQ TRAN_SEQ22,
                              VT.TRANS_DATE_H TRANS_DATE_H22
                              FROM
                              --VHCL_TRANSACTIONS VT1,
                              VHCL_TRANSACTIONS VT,
                              DCLTN_LAND_MNFST_TRANS DLMT,
                              DCLTN_LAND_MNFSTS DLM
                              where
                               --VT1.PORT_CD                                     = VT.PORT_CD
                              --AND VT1.REC_TRAN_SEQ                  = VT.TRAN_SEQ
                              --AND VT1.REC_TRANS_DATE_H         = VT.TRANS_DATE_H AND
                               DLMT.PORT_CD                                    = VT.PORT_CD
                              AND DLMT.TRAN_SEQ                          = VT.TRAN_SEQ
                              AND DLMT.TRANS_DATE_H                 = VT.TRANS_DATE_H
                              AND DLM.PORT_CD                               = DLMT.PORT_CD
                              AND DLM.DCLTN_MNFST_ISN              = DLMT.DCLTN_MNFST_ISN
                             ) WHERE PORT_CD22 = h.PORT_CD21 AND DCLTN_ISN22 = h.DCLTN_ISN2 ORDER BY PORT_CD22, TRAN_SEQ22, TRANS_DATE_H22, DCLTN_ISN22)
            LOOP
                v_l := v_l || CASE WHEN v_l IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (p.PLATE_NO22 || '   ' || p.CHASSIS_NO22);

                FOR r IN (SELECT * FROM (
                              SELECT
                              VT1.VHCL_CHASSIS_NO     REC_CHASSIS_NO22,
                              VT1.PORT_CD                      port_cd222,
                              VT1.REC_TRAN_SEQ          REC_TRAN_SEQ22,
                              VT1.REC_TRANS_DATE_H REC_TRANS_DATE_H22
                              from
                              VHCL_TRANSACTIONS VT1
                                 ) WHERE PORT_CD222 = p.PORT_CD22 AND REC_TRAN_SEQ22 = p.TRAN_SEQ22 AND REC_TRANS_DATE_H22 = p.TRANS_DATE_H22
                           ORDER BY REC_CHASSIS_NO22)
                LOOP
                    cs_car := cs_car + CASE WHEN r.REC_CHASSIS_NO22 IS NOT NULL THEN 1 ELSE 0 END;
                    v_rec := v_rec || CASE WHEN v_rec IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.REC_CHASSIS_NO22);
                END LOOP;
            END LOOP;

            IF cs_g_p_no <> 0 THEN
                v_b17 := v_b17 || '<br/>' || '<b style="color:#0e0f50;">رقم اللوحة / رقم الشاسيه</b> ' || '<br/>' || v_l;
            END IF;

            IF cs_car > 4 THEN
                v_b17 := v_b17 || '<br/>مرفق ملحق بأرقام شاسيهات السيارات';   -- B_ATTACHED1
            ELSIF v_rec IS NOT NULL THEN
                v_b17 := v_b17 || '<br/>' || v_rec;   -- M_89
            END IF;

            -- 6 / 9 / 12 / 15: المستورد (M_73) أو المصدر (M_71)، والوسيطة لو غير المستورد، والسجل التجاري، والرقم الضريبي والمصدر إليه (الصادر)

            v_b6 := CASE WHEN h.DCLTN_TYPE_CD IN (1, 2) THEN APEX_ESCAPE.HTML (h.T_IMPR_NAME) ELSE APEX_ESCAPE.HTML (h.AGNT_NAME) END;
            v_b9 := CASE WHEN h.AGNT_NAME <> h.T_IMPR_NAME THEN APEX_ESCAPE.HTML (h.AGNT_NAME) END;
            v_b12 := APEX_ESCAPE.HTML (h.IMPR_BUS_ID || '   ' || h.IMPR_BUS_ID_BRNCH);
            IF h.EXP_BUS_ID IS NOT NULL OR h.EXP_BUS_ID_BRNCH IS NOT NULL THEN
                v_b12 := v_b12 || '<br/>' || APEX_ESCAPE.HTML (h.EXP_BUS_ID || '   ' || h.EXP_BUS_ID_BRNCH);
            END IF;
            v_b15 := APEX_ESCAPE.HTML (TIN_NOFormula (h.DCLTN_ISN2)) ||   -- TIN_NO formula (F_EXPORT_TO1)
             CASE WHEN NOT (h.DCLTN_TYPE_CD IN (1, 2)) THEN '<br/>' || APEX_ESCAPE.HTML (h.EXPORT_TO) END;

            -- 18 ميناء الشحن: الوارد (M_38، R_3) من المنافيست، والصادر (M_32) الجمرك الحالي؛ 20 ميناء التفريغ (M_61، R_4)

            IF h.DCLTN_TYPE_CD IN (1, 2) THEN
            v_b18 := NULL;
            FOR r IN (SELECT * FROM (
                              SELECT
                              DLM.DCLTN_ISN DCLTN_ISN,
                              DLM.FRGN_MAN_NO        MAN_NO,
                              DLM.FRGN_MAN_DATE    MAN_DT,
                              DLM.CTRY_CD                   CTRY_CD,
                              DLM.FR_PORT_CD            FR_PORT_CD,
                              DLM.PORT_CD                   PORT_CD,
                              DLM.DCLTN_MNFST_ISN DCLTN_MNFST_ISN
                              FROM
                              DCLTN_LAND_MNFSTS DLM
                              WHERE DLM.DCLTN_ISN               = h.DCLTN_ISN2
                              AND       DLM.PORT_CD                  = h.PORT_CD21
                             ) ORDER BY MAN_NO)
            LOOP
                v_b18 := v_b18 || CASE WHEN v_b18 IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.FR_PORT_CD || '  ' || CF_INTL_CTRY_NAMEFormula (r.CTRY_CD));
            END LOOP;
            v_b20 := NULL;
            FOR r IN (SELECT * FROM (
                              SELECT
                              DLM.DCLTN_ISN DCLTN_ISN,
                              DLM.FRGN_MAN_NO        MAN_NO,
                              DLM.FRGN_MAN_DATE    MAN_DT,
                              DLM.CTRY_CD                   CTRY_CD,
                              DLM.FR_PORT_CD            FR_PORT_CD,
                              DLM.PORT_CD                   PORT_CD,
                              DLM.DCLTN_MNFST_ISN DCLTN_MNFST_ISN
                              FROM
                              DCLTN_LAND_MNFSTS DLM
                              WHERE DLM.DCLTN_ISN               = h.DCLTN_ISN2
                              AND       DLM.PORT_CD                  = h.PORT_CD21
                             ) ORDER BY MAN_NO)
            LOOP
                v_b20 := v_b20 || CASE WHEN v_b20 IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (CF_PORT_NAMEFormula (h.PORT_CD21));
            END LOOP;
            ELSE
                v_b18 := APEX_ESCAPE.HTML (CF_PORT_OF_LOADINGFormula);
                v_b20 := NULL;
            END IF;

            -- 19 الرصاصات ومكانها (R_9 / Q_3)، وصندوق التتبع (R_14) والأقفال (R_13) لكل لوحة

            v_b19 := NULL;
            FOR r IN (SELECT * FROM (
                              SELECT DISTINCT
                              DLM.DCLTN_ISN DCLTN_ISN,
                              DLM.PORT_CD                   PORT_CD11,
                              SEAL_NO,
                              SEAL_LOC_NAME
                              FROM
                              DCLTN_LAND_MNFSTS DLM,
                              DCLTN_LAND_MNFST_TRANS DLMT ,
                              VHCL_SEALS VS,
                              SEAL_LOCS SL
                              WHERE
                                              DLMT.PORT_CD                   = dlm.PORT_CD
                              AND        DLMT.DCLTN_MNFST_ISN  = dlm.DCLTN_MNFST_ISN
                              AND       vs.PORT_CD              =  DLMT.PORT_CD
                              AND       vs.TRAN_SEQ            =  DLMT.TRAN_SEQ
                              AND        vs.TRANS_DATE_H  =  DLMT.TRANS_DATE_H
                              and         VS.SEAL_LOC_CD=SL.SEAL_LOC_CD
                              union
                              SELECT DISTINCT
                              DGT.DCLTN_ISN ,
                              DGT.PORT_CD    ,
                              SEAL_NO,
                              SEAL_LOC_NAME
                              FROM
                              DCLTN_GATE_TRANS DGT,
                              VHCL_SEALS VS,
                              SEAL_LOCS SL
                              WHERE
                                            vs.PORT_CD              =  DGT.PORT_CD
                              AND       vs.TRAN_SEQ            =  DGT.VHCL_TRANS_NBR
                              AND        vs.TRANS_DATE_H  =  DGT.VHCL_TRANS_DATE
                              and         VS.SEAL_LOC_CD=SL.SEAL_LOC_CD
                             ) WHERE PORT_CD11 = h.PORT_CD21 AND DCLTN_ISN = h.DCLTN_ISN2 ORDER BY SEAL_NO)
            LOOP
                v_b19 := v_b19 || CASE WHEN v_b19 IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.SEAL_NO) || ' <b style="color:#0e0f50;">مكانها</b> ' || APEX_ESCAPE.HTML (r.SEAL_LOC_NAME);
            END LOOP;

            FOR m IN (SELECT * FROM (
                              SELECT
                              DLM.DCLTN_ISN DCLTN_ISN,
                              DLM.FRGN_MAN_NO        MAN_NO,
                              DLM.FRGN_MAN_DATE    MAN_DT,
                              DLM.CTRY_CD                   CTRY_CD,
                              DLM.FR_PORT_CD            FR_PORT_CD,
                              DLM.PORT_CD                   PORT_CD,
                              DLM.DCLTN_MNFST_ISN DCLTN_MNFST_ISN
                              FROM
                              DCLTN_LAND_MNFSTS DLM
                              WHERE DLM.DCLTN_ISN               = h.DCLTN_ISN2
                              AND       DLM.PORT_CD                  = h.PORT_CD21
                             ) ORDER BY MAN_NO)
            LOOP
                FOR t IN (SELECT * FROM (
                              SELECT
                               DLMT.TRAN_SEQ TRAN_SEQ,
                               DLMT.TRANS_DATE_H TRAN_DT,
                               DLMT.DCLTN_MNFST_ISN MNFST_ISN,
                               DLMT.PORT_CD PORT_CD
                              FROM
                              DCLTN_LAND_MNFST_TRANS DLMT
                              WHERE DLMT.DCLTN_MNFST_ISN  = m.DCLTN_MNFST_ISN
                              AND       DLMT.PORT_CD                   = m.PORT_CD
                                 ) ORDER BY TRAN_SEQ)
                LOOP
                    FOR p IN (SELECT * FROM (
                              SELECT DISTINCT
                              VT.PLATE_NO PLATE_NO,
                              VT.VHCL_CHASSIS_NO CHASSIS_NO,
                              VT.TRAN_SEQ TRAN_SEQ,
                              VT.TRANS_DATE_H TRAN_DT,
                              VT.PORT_CD PORT_CD,
                              VT.PSPRT_NO                  VT_PSPRT_NO,
                              VT.PSPRT_ISSUE_DATE VT_PSPRT_ISSUE_DATE,
                              DR.DRIVER_NAME DRIVER_NAME
                              FROM
                              VHCL_TRANSACTIONS VT,VHCL_DRIVERS DR
                              WHERE  VT.TRAN_SEQ           = t.TRAN_SEQ
                              AND        VT.TRANS_DATE_H  = t.TRAN_DT
                              AND        VT.PORT_CD              = t.PORT_CD
                              AND        VT.PSPRT_NO = DR.PSPRT_NO
                              AND        VT.PSPRT_ISSUE_DATE = DR.PSPRT_ISSUE_DATE
                              AND        VT.DRIVER_CTRY_CD    =  DR.CTRY_CD
                              AND        VT.DOC_TYPE    =  DR.DOC_TYPE
                                     ) ORDER BY TRAN_SEQ)
                    LOOP
                        FOR r IN (SELECT * FROM (
                              SELECT VB.PORT_CD, VB.TRANS_DATE_H, VB.TRAN_SEQ,   VB.BOX_NBR,  VL.LOCK_NBR, LOCK_LOC_CD, SL.SEAL_LOC_NAME LOCK_LOC_NAME
                                 FROM VHCL_BOXES VB, VHCL_LOCKS VL, SEAL_LOCS  SL
                                 WHERE VL.PORT_CD                = VB.PORT_CD
                                        AND  VL.TRANS_DATE_H = VB.TRANS_DATE_H
                              		  AND  VL.TRAN_SEQ             = VB.TRAN_SEQ
                              		  AND SL.SEAL_LOC_CD       = VL.LOCK_LOC_CD
                                         ) WHERE PORT_CD = p.PORT_CD AND TRANS_DATE_H = p.TRAN_DT AND TRAN_SEQ = p.TRAN_SEQ)
                        LOOP
                            v_b19 := v_b19 || CASE WHEN v_b19 IS NOT NULL THEN '<br/>' END
                                     || CASE WHEN r.BOX_NBR IS NOT NULL THEN '<b style="color:#0e0f50;">رقم صندوق التتبع</b> ' || APEX_ESCAPE.HTML (r.BOX_NBR) END
                                     || CASE WHEN r.LOCK_NBR IS NOT NULL THEN ' ' || APEX_ESCAPE.HTML (r.LOCK_NBR) || ' ' || APEX_ESCAPE.HTML (r.LOCK_LOC_NAME) END;
                        END LOOP;
                    END LOOP;
                END LOOP;
            END LOOP;

            -- التعهدات (G_ISSUED_DT / G_ITEM_SER_NBR: الحالة <> 9) والفواتير (R_20) والمرفقات (R_7) والتحصيل (R_10)

            v_wvr := NULL;
            FOR r IN (SELECT DISTINCT WVR_SEQ_NBR, ISSUED_DT, ITEM_TYPE_CD, ITEM_SER_NBR, ITEM_STATUS FROM (
                              SELECT
                              T1.TYPE_ID L_DCLTNT_TYPE_ID,
                              T0.DCLTN_NBR DCLTN_NBR,
                              T3.ARBC_IMPR_NAME T_IMPR_NAME,
                              T5.ARBC_IMPR_NAME AGNT_NAME,
                              T2.PORT_CD L_USR_PORT_CD,
                              T2.USER_ID L_USR_USER_ID,
                              T2.USR_ANAME INSP_NAME,
                              T3.PORT_CD L_IMP_PORT_CD2,
                              T3.IMPR_NBR L_IMP_IMPR_NBR2,
                              T4.PORT_CD L_BKM_PORT_CD,
                              T4.LIC_TYPE L_BKM_LIC_TYPE,
                              T4.LIC_NBR L_BKM_LIC_NBR,
                              T4.BRKR_NAME BRKR_NAME,
                              T4.LIC_CATEGORY,
                              T4.CHANGE_CATG_DATE,
                              T4.TRADE_NAME,
                              T5.PORT_CD L_IMP_PORT_CD,
                              T5.IMPR_NBR L_IMP_IMPR_NBR,
                              T3.BUS_ID IMPR_BUS_ID,
                              T0.PORT_CD PORT_CD21,
                              T0.REPRINT_RSN_CD,
                              T0.DCLTN_ISN DCLTN_ISN2,
                              T0.DCLTN_TYPE_CD DCLTN_TYPE_CD,
                              T0.DCLTN_DT DCLTN_DT,
                              T1.TYPE_NAME DCLTN_TYPE_NAME,
                              T0.BRKR_PORT_CD BRKR_PORT_CD,
                              T0.IMPR_NBR IMPR_NBR,
                              T0.AGENT_NBR DCLTN_AGENT_NBR,
                               T0.INSPTR_ID INSPTR_ID,
                              T0.LIC_NBR LIC_NBR,
                              T0.LIC_TYPE LIC_TYPE,
                              T3.BUS_ID_BRNCH IMPR_BUS_ID_BRNCH,
                              T5.BUS_ID EXP_BUS_ID,
                              T5.BUS_ID_BRNCH EXP_BUS_ID_BRNCH,
                              T0.PMT_METHOD PMT_METHOD,
                              T0.PRINT_CNT,
                              T0.DHL_BL,
                              T0.DHL_OWNER,
                              T0.CLRNC_DT,
                              T0.EXPORT_TO EXPORT_TO,
                              T0.FINAL_CTRY_CD FINAL_CTRY_CD,
                              T0.EXIT_PORT_CD EXIT_PORT_CD,
                              T0.CL_NBR CL_NBR,
                              T0.CL_DT CL_DT,
                              T0.CL_VAL CL_VAL,
                              T0.RSTRCD_ITEMS RSTRCD_ITEMS,
                              T0.DCLTN_STA_CD DCLTN_STATUS,
                              T6.DOC_INS_NBR,
                              T6.DOC_INS_DT,
                              T6.RCPT_NBR RCPT_NBR22,
                              T14.ATM_AUTHRZTN_CD ATM_AUTHRZTN_CD22,
                              T6.RCPT_TYPE RCPT_TYPE22,
                              T6.COLL_DT,
                              T6.BANK_CD CO_BANK_CD,
                              T6.BANK_BRNCH_CD CO_BANK_BRNCH_CD,
                              T6.COLL_ORDR_STA COLL_ORDR_STA1,
                              --T6.IVR_NBR,
                              T0.GROUP_ID GROUP_ID,
                              WI.ITEM_TYPE_CD,
                              WI.ISSUED_DT, WI. ITEM_SER_NBR,
                              W.WVR_SEQ_NBR,
                              WI.ITEM_STATUS,
                              T0.GATE_DT,
                              IMPORT_DCLTN_ISN
                              FROM
                              COLL_ORDERS T6,
                              BANK_RCPTS T14,
                              IMPORTERS T5,
                              BRKR_MSTR T4,
                              IMPORTERS T3,
                              SC_USERS T2,
                              DCLTN_TYPES T1,
                              DECLARATIONS T0,
                              WAIVERS W, WVR_ITEMS WI
                              WHERE
                              T0.DCLTN_TYPE_CD = T1.TYPE_ID AND
                              T0.PORT_CD = T2.PORT_CD (+) AND
                              T0.INSPTR_ID = T2.USER_ID (+) AND
                              T0.PORT_CD = T3.PORT_CD (+) AND
                              T0.IMPR_NBR = T3.IMPR_NBR (+) AND
                              T0.BRKR_PORT_CD = T4.PORT_CD (+) AND
                              T0.LIC_TYPE = T4.LIC_TYPE (+) AND
                              T0.LIC_NBR = T4.LIC_NBR (+) AND
                              T0.PORT_CD = T5.PORT_CD AND
                              T0.AGENT_NBR = T5.IMPR_NBR AND
                              T0.PORT_CD  =   v_p_curr_port_cd  AND
                              T0.DCLTN_ISN = v_cg_p_p_dcltn_isn AND
                              T6.PORT_CD   (+) = T0.PORT_CD AND
                              T6.COLL_ORDR_NBR (+)  = T0.DCLTN_NBR  AND
                              T6.COLL_ORDR_DT (+)     = T0.DCLTN_DT AND
                              T6.COLL_ORDR_CTGRY (+) = T0.DCLTN_TYPE_CD
                              AND
                              T6.PORT_CD = T14.PORT_CD (+) AND
                              T6.BANK_CD = T14.BANK_CD (+) AND
                              T6.BANK_BRNCH_CD = T14.BANK_BRNCH_CD (+) AND
                              T6.COLL_DT = T14.REV_DT (+) AND
                              T6.RCPT_NBR = T14.RCPT_NBR (+) AND
                              T6.RCPT_TYPE = T14.RCPT_TYPE (+)
                              AND  T0.PORT_CD  =W.WVR_PORT_CD (+)
                              AND T0.DCLTN_ISN =  W.DCLTN_ISN(+)
                              AND  WI.WVR_PORT_CD  (+) = W.WVR_PORT_CD
                                AND         WI.WVR_SEQ_NBR    (+) = W.WVR_SEQ_NBR
                                AND         WI.ISSUED_DT        (+) = W.ISSUED_DT
                             ) WHERE PORT_CD21 = h.PORT_CD21 AND DCLTN_ISN2 = h.DCLTN_ISN2 AND WVR_SEQ_NBR IS NOT NULL AND NVL (ITEM_STATUS, 0) != 9
                       ORDER BY WVR_SEQ_NBR, ISSUED_DT, ITEM_TYPE_CD, ITEM_SER_NBR)
            LOOP
                v_wvr := v_wvr || CASE WHEN v_wvr IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.WVR_SEQ_NBR || '  ' || TO_CHAR (r.ISSUED_DT, 'MI-MM-RRRR') || '  ' || CF_ITM_TYPE_MEANFormula (r.ITEM_TYPE_CD) || '  ' || r.ITEM_SER_NBR);
            END LOOP;

            v_inv := NULL;
            v_cnt := 0;

            FOR i IN (SELECT * FROM (
                              SELECT
                              T11.CURCY_CD L_CUR_CURCY_CD,
                              T7.CTRY_CD L_CTRY_CTRY_CD1,
                              T6.FINAL_TARIFF_CD FINAL_TARIFF_CD,
                              T9.INTL_MSR_UNIT L_IMU_INTL_MSR_UNIT,
                              T8.TYPE_CD L_ET_TYPE_CD,
                              T6.EXMTN_TYPE EXMTN_CD,
                              T8.TYPE_NAME EXMTN_SRCE,
                              T6.PORT_CD PORT_CD1,
                              T10.PORT_CD PORT_CD3,
                              T10.INV_ISN INV_ISN2,
                              T6.ITEM_ISN ITEM_ISN,
                              T10.INV_SEQ INV_SEQ,
                              T6.ITEM_SEQ ITEM_SEQ1,
                              T6.DCLTN_ISN DCLTN_ISN1,
                              T10.INV_NBR INV_NBR,
                              T6.INV_ISN INV_ISN,
                              T10.INV_TYPE INV_TYPE,
                              T6.CTRY_CD CTRY_CD,
                              T10.DCLTN_ISN DCLTN_ISN3,
                              T10.INV_CURCY_CD DCLTN_INV_INV_CURCY_CD,
                              T6.FINAL_TARIFF_DT FINAL_TARIFF_DT,
                              T6.ITEM_DESC ITEM_DESC,
                              T7.CTRY_INTL_CD ORIGIN,
                              T6.INV_COST INV_COST,
                              T11.CURCY_INTL_CD CURCY_INTL_CD,
                              T6.CIF_COST CIF_COST,
                              T6.DUTY_TYPE INCOME_TYPE,
                              T6.INTL_MSR_UNIT INTL_MSR_UNIT,
                              T6.INTL_QTY INTL_QTY,
                              T9.IMSR_ARBC_NAME MSR_UNIT_NAME,
                              T6.NET_WT NET_WT,
                              T6.GROSS_WT GROSS_WT,
                              T6.ORGNL_DUTY ORGNL_DUTY,
                              T6.EXMTD_DUTY EXMTD_DUTY,
                              T6.TRF_UNIT_QTY TRF_UNIT_QTY,
                              T6.INV_QTY,
                              T6.INV_MSR_UNIT,
                              T12.MSR_ARBC_NAME,
                              T6.EXMTN_DECREE_PORT_CD,
                              T6.EXMTN_DECREE_ISN,
                              T6.EXMTN_ITEM_SEQ,
                              T6.EXMTN_ITEM_SUB_SEQ,
                              T6.TEMP_ITEM,
                              T6.ANAL_ITEM_CODE_1,
                              T6.ANAL_ITEM_CODE_2,
                              T10.INV_PMT_METHOD
                              FROM
                              CURRENCIES T11,
                              DCLTN_INVOICES T10,
                              INTL_MSR_UNITS T9,
                              EXMTN_TYPES T8,
                              COUNTRIES T7,
                              DCLTN_ITEMS T6,
                              MEASURE_UNITS T12
                              WHERE
                              h.PORT_CD21 = T6.PORT_CD AND
                              h.DCLTN_ISN2 = T6.DCLTN_ISN AND
                              T6.CTRY_CD = T7.CTRY_CD AND
                              T6.EXMTN_TYPE = T8.TYPE_CD (+) AND
                              T6.INTL_MSR_UNIT = T9.INTL_MSR_UNIT AND
                              T6.INV_MSR_UNIT  = T12.MSR_UNIT AND
                              T6.PORT_CD = T10.PORT_CD (+) AND
                              T6.INV_ISN = T10.INV_ISN (+) AND
                              T10.INV_CURCY_CD = T11.CURCY_CD (+)
                              ORDER BY  INV_SEQ,ITEM_SEQ1
                             ) ORDER BY ITEM_SEQ1, INV_SEQ)
            LOOP
                IF i.INV_TYPE IS NOT NULL THEN
                    v_cnt := v_cnt + 1;   -- CS_ITEM_COUNT
                END IF;

                v_inv := v_inv || CASE WHEN v_inv IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (CF_ITEM_COUNTFormula (v_cnt, i.INV_TYPE) || ' ' || CF_INV_TYPEFormula (i.INV_TYPE) || ' ' || i.INV_NBR || ' ' || CF_INV_PMNT_MTHOD_MEANFormula (i.INV_PMT_METHOD));
            END LOOP;

            v_docs := NULL;
            FOR r IN (SELECT * FROM (
                              SELECT DISTINCT
                              PORT_CD DOC_PORT_CD,
                              DCLTN_ISN DOC_DCLTN_ISN ,
                              DOC_TYPE DOC_DOC_TYPE,
                              DOC_NBR DOC_DOC_NBR,
                              ' '||RV_MEANING  DOC_DESC
                              FROM
                              DCLTN_DOCS,
                              CG_REF_CODES
                              WHERE
                              RV_DOMAIN = 'DOC_TYPE'
                              AND
                              RV_LOW_VALUE = DOC_TYPE
                             ) WHERE DOC_PORT_CD = h.PORT_CD21 AND DOC_DCLTN_ISN = h.DCLTN_ISN2 ORDER BY DOC_DOC_NBR, DOC_DESC)
            LOOP
                v_docs := v_docs || CASE WHEN v_docs IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.DOC_DESC || '   ' || r.DOC_DOC_NBR);
            END LOOP;

            v_coll := NULL;
            FOR r IN (SELECT * FROM (
                              SELECT
                              T16.BANK_CD L_BC_BANK_CD,
                              T15.BANK_CD L_BBC_BANK_CD,
                              T15.BANK_BRNCH_CD L_BBC_BANK_BRNCH_CD,
                              T14.PORT_CD L_BR_PORT_CD,
                              T14.BANK_CD L_BR_BANK_CD,
                              T14.BANK_BRNCH_CD L_BR_BANK_BRNCH_CD,
                              T14.REV_DT L_BR_REV_DT,
                              T14.RCPT_NBR L_BR_RCPT_NBR,
                              T13.PORT_CD PORT_CD2,
                              T13.COLL_ORDR_NBR COLL_ORDR_NBR2,
                              T13.COLL_ORDR_DT COLL_ORDR_DT2,
                              T13.COLL_ORDR_CTGRY COLL_ORDR_CTGRY2,
                              T13.DCLTN_ISN DCLTN_ISN,
                              T13.DOC_INS_NBR DOC_INS_NBR,
                              T13.DOC_INS_DT DOC_INS_DT,
                              T13.RCPT_NBR RCPT_NBR,
                              T13.COLL_DT RCPT_DT,
                              T14.RCPT_TYPE RCPT_TYPE1,
                              T14.ATM_AUTHRZTN_CD ATM_AUTHRZTN_CD,
                              T16.BANK_NAME BANK_NAME,
                              T15.BANK_BRNCH_NAME BANK_BRNCH_NAME,
                              T13.BANK_CD BANK_CD,
                              T13.BANK_BRNCH_CD BANK_BRNCH_CD,
                              T12.ACCT_SEQ ACCT_SEQ,
                              T13.COLL_ORDR_STA COLL_ORDR_STA,
                              T12.AMT AMT,
                              T12.SRCE_PORT_AMT SRCE_PORT_AMT,
                              T12.PORT_CD PORT_CD4,
                              T12.COLL_ORDR_NBR COLL_ORDR_NBR,
                              T12.COLL_ORDR_DT COLL_ORDR_DT,
                              T12.COLL_ORDR_CTGRY COLL_ORDR_CTGRY
                              FROM
                              BANKS T16,
                              BANK_BRNCHS T15,
                              BANK_RCPTS T14,
                              COLL_ORDERS T13,
                              COLL_ORDER_DTLS T12
                              WHERE
                              h.PORT_CD21 = T13.PORT_CD AND
                              h.DCLTN_ISN2 = T13.DCLTN_ISN AND
                              T12.PORT_CD = T13.PORT_CD AND
                              T12.COLL_ORDR_NBR = T13.COLL_ORDR_NBR AND
                              T12.COLL_ORDR_DT = T13.COLL_ORDR_DT AND
                              T12.COLL_ORDR_CTGRY = T13.COLL_ORDR_CTGRY AND
                              h.PORT_CD21 = T13.PORT_CD AND
                              h.DCLTN_ISN2 = T13.DCLTN_ISN AND
                              T13.PORT_CD = T14.PORT_CD (+) AND
                              T13.BANK_CD = T14.BANK_CD (+) AND
                              T13.BANK_BRNCH_CD = T14.BANK_BRNCH_CD (+) AND
                              T13.COLL_DT = T14.REV_DT (+) AND
                              T13.RCPT_NBR = T14.RCPT_NBR (+) AND
                              T13.RCPT_TYPE = T14.RCPT_TYPE (+) AND
                              h.PORT_CD21 = T13.PORT_CD AND
                              h.DCLTN_ISN2 = T13.DCLTN_ISN AND
                              T14.CHECK_BANK_CD = T15.BANK_CD (+) AND
                              T14.CHECK_BRNCH_CD = T15.BANK_BRNCH_CD (+) AND
                              h.PORT_CD21 = T13.PORT_CD AND
                              h.DCLTN_ISN2 = T13.DCLTN_ISN AND
                              T15.BANK_CD = T16.BANK_CD (+) AND
                              h.PORT_CD21 = T13.PORT_CD AND
                              h.DCLTN_ISN2 = T13.DCLTN_ISN
                             ) ORDER BY DOC_INS_NBR, RCPT_NBR)
            LOOP
                v_coll := v_coll || CASE WHEN v_coll IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (CF_COLL_STA_7Formula (r.COLL_ORDR_STA, r.PORT_CD2, r.COLL_ORDR_NBR, r.COLL_ORDR_DT, r.COLL_ORDR_CTGRY));
            END LOOP;

            IF NOT v_first THEN
                dbms_lob.append (retVal, '<div style="page-break-before: always"></div>');
            END IF;

            v_first := FALSE;
            dbms_lob.append (retVal, '
              <table dir="rtl" style="width:100%;table-layout:fixed;border-collapse:collapse;"><tr><td style="width:30%;vertical-align:top;font-size:12px;color:#0e0f50;font-weight:bold;">' || CASE WHEN v_cg_p_p_reprint = 1 THEN 'بـــدل تــالـــف' END || '<br/>' || CASE WHEN v_cg_p_p_impr_diff_clrnc = 1 THEN '[ خ . ت ]' END || '</td><td style="width:40%;text-align:center;vertical-align:top;font-size:11px;color:#0e0f50;">' || CASE WHEN NVL (v_ivr, 0) <> 0 THEN 'رقم مصلحة الجمارك بنظام سداد: 030<br/>' END || '' || CASE WHEN v_ivr IS NOT NULL THEN 'الرقم الموحد: <b>' || APEX_ESCAPE.HTML (v_ivr) || '</b><br/>' END || '' || CASE WHEN FOR_INCOME_TYPE (h.DCLTN_TYPE_CD) THEN '<b style="font-size:13px;">بيان جمركي مؤقت</b><br/>' END || '' || APEX_ESCAPE.HTML (v_p_bank_txt) || '</td><td style="width:30%;vertical-align:top;text-align:left;font-size:10px;color:#0e0f50;">' || APEX_ESCAPE.HTML (v_cg_p_p_prnt_cd) || '' || CASE WHEN h.FINAL_CTRY_CD <> 100 AND h.RSTRCD_ITEMS = 1 THEN '<br/>سلع مقيده - رسوم المقاصة : ' || APEX_ESCAPE.HTML (v_sum_duty) END || '</td></tr></table>
              <table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="width:25%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">1 رقم البيان <span style="font-weight:normal;">.Dec No</span></div>' || APEX_ESCAPE.HTML (h.DCLTN_NBR) || '</td></tr></table></td><td style="width:25%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">2 تاريخ البيان <span style="font-weight:normal;">Dec Date</span></div>' || APEX_ESCAPE.HTML (TO_CHAR (h.DCLTN_DT, 'mi-mm-yyyy')) || '<br/>' || APEX_ESCAPE.HTML (CF_DCLTN_DT_GFormula (h.DCLTN_DT)) || '</td></tr></table></td><td style="width:25%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">3 نوع البيان <span style="font-weight:normal;">Dec Type</span></div>' || APEX_ESCAPE.HTML (h.DCLTN_TYPE_NAME) || '</td></tr></table></td><td style="width:25%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">4 نوع المنفذ <span style="font-weight:normal;">Port Type</span></div>' || APEX_ESCAPE.HTML (CF_PORT_TYPEFormula) || '</td></tr></table></td></tr></table>
              <table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="width:33%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">5 رقم إذن التسليم <span style="font-weight:normal;">.Delivery Order No</span></div>' || v_b5 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">8 الناقلة / القبطان / السائق <span style="font-weight:normal;">Carrier \ Captain \ Driver</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">11 اسم الناقلة <span style="font-weight:normal;">Carrier</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">14 رقم الرحلة <span style="font-weight:normal;">.Voyage \ Flight No</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">17 رقم البوليصة / المنافيست <span style="font-weight:normal;">.B\L- AWB No. / Manifest</span></div>' || v_b17 || '</td></tr></table></td><td style="width:31%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">6 المستورد / المصدر <span style="font-weight:normal;">Importer \ Exporter</span></div>' || v_b6 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">9 الشركة الوسيطة <span style="font-weight:normal;">.Intercessor Co</span></div>' || v_b9 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">12 رقم السجل التجاري <span style="font-weight:normal;">.Commercial Reg. No</span></div>' || v_b12 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">15 المصدر إليه <span style="font-weight:normal;">Exported To</span></div>' || v_b15 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">18 ميناء الشحن <span style="font-weight:normal;">Port of Loading</span></div>' || v_b18 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">20 ميناء التفريغ <span style="font-weight:normal;">Port of Discharge</span></div>' || v_b20 || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">21 جهة المقصد <span style="font-weight:normal;">Destination</span></div>' || APEX_ESCAPE.HTML (CF_FINAL_CTRY_DESCFormula (h.FINAL_CTRY_CD)) || '</td></tr></table></td><td style="width:36%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">7 الوزن الصافي <span style="font-weight:normal;">Net Weight</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">10 الوزن القائم <span style="font-weight:normal;">Gross Weight</span></div>' || APEX_ESCAPE.HTML (cs_gross_wt) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">13 القياس <span style="font-weight:normal;">Measurement</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">16 عدد الطرود <span style="font-weight:normal;">No. of Packages</span></div>' || APEX_ESCAPE.HTML (cs_item_qty) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">19 العلامات والأرقام <span style="font-weight:normal;">Marks ' || CHR (38) || ' Numbers</span></div>' || '<b style="color:#0e0f50;">الرصاصات / مكانها</b><br/>' || v_b19 || '</td></tr></table></td></tr></table>
              <p style="text-align:center;margin:4px 0;"><object type="image/barcode" format="CODE_128" style="width:300px;height:26px;" value="' || APEX_ESCAPE.HTML_ATTRIBUTE (v_bar) || '"></object></p>');

            -- 22 - 31: صف لكل صنف (CG$G_DCLTN_ITEMS) بحرف الصف (أ - هـ)
            dbms_lob.append (retVal, '<table class="data" dir="rtl" style="border-collapse:collapse;width:100%;table-layout:fixed;margin-top:4px;"><thead><tr><th style="width:3%;font-size:9px;"></th><th style="width:10%;font-size:9px;">22 بنـد التعـرفـة<br/>H.T. Code</th><th style="width:22%;font-size:9px;">23 وصــف البــضــاعــة<br/>Goods Description</th><th style="width:7%;font-size:9px;">24 بلد المنشأ<br/>Origin</th><th style="width:9%;font-size:9px;">25 القيمة بالعملة الأجنبية<br/>Foreign Value</th><th style="width:5%;font-size:9px;">26 العملة النوع<br/>Type</th><th style="width:7%;font-size:9px;">27 السعر<br/>Rate</th><th style="width:10%;font-size:9px;">28 القيمة بالعملة المحلية<br/>CIF Local Value ريال SR</th><th style="width:7%;font-size:9px;">29 فئة الرسم<br/>D. Rate</th><th style="width:8%;font-size:9px;">30 نوع الإيراد<br/>Income Type</th><th style="width:12%;font-size:9px;">31 إجمالي الرسوم<br/>Total Duty ريال SR</th></tr></thead><tbody>');
            v_n := 0;

            FOR i IN (SELECT * FROM (
                              SELECT
                              T11.CURCY_CD L_CUR_CURCY_CD,
                              T7.CTRY_CD L_CTRY_CTRY_CD1,
                              T6.FINAL_TARIFF_CD FINAL_TARIFF_CD,
                              T9.INTL_MSR_UNIT L_IMU_INTL_MSR_UNIT,
                              T8.TYPE_CD L_ET_TYPE_CD,
                              T6.EXMTN_TYPE EXMTN_CD,
                              T8.TYPE_NAME EXMTN_SRCE,
                              T6.PORT_CD PORT_CD1,
                              T10.PORT_CD PORT_CD3,
                              T10.INV_ISN INV_ISN2,
                              T6.ITEM_ISN ITEM_ISN,
                              T10.INV_SEQ INV_SEQ,
                              T6.ITEM_SEQ ITEM_SEQ1,
                              T6.DCLTN_ISN DCLTN_ISN1,
                              T10.INV_NBR INV_NBR,
                              T6.INV_ISN INV_ISN,
                              T10.INV_TYPE INV_TYPE,
                              T6.CTRY_CD CTRY_CD,
                              T10.DCLTN_ISN DCLTN_ISN3,
                              T10.INV_CURCY_CD DCLTN_INV_INV_CURCY_CD,
                              T6.FINAL_TARIFF_DT FINAL_TARIFF_DT,
                              T6.ITEM_DESC ITEM_DESC,
                              T7.CTRY_INTL_CD ORIGIN,
                              T6.INV_COST INV_COST,
                              T11.CURCY_INTL_CD CURCY_INTL_CD,
                              T6.CIF_COST CIF_COST,
                              T6.DUTY_TYPE INCOME_TYPE,
                              T6.INTL_MSR_UNIT INTL_MSR_UNIT,
                              T6.INTL_QTY INTL_QTY,
                              T9.IMSR_ARBC_NAME MSR_UNIT_NAME,
                              T6.NET_WT NET_WT,
                              T6.GROSS_WT GROSS_WT,
                              T6.ORGNL_DUTY ORGNL_DUTY,
                              T6.EXMTD_DUTY EXMTD_DUTY,
                              T6.TRF_UNIT_QTY TRF_UNIT_QTY,
                              T6.INV_QTY,
                              T6.INV_MSR_UNIT,
                              T12.MSR_ARBC_NAME,
                              T6.EXMTN_DECREE_PORT_CD,
                              T6.EXMTN_DECREE_ISN,
                              T6.EXMTN_ITEM_SEQ,
                              T6.EXMTN_ITEM_SUB_SEQ,
                              T6.TEMP_ITEM,
                              T6.ANAL_ITEM_CODE_1,
                              T6.ANAL_ITEM_CODE_2,
                              T10.INV_PMT_METHOD
                              FROM
                              CURRENCIES T11,
                              DCLTN_INVOICES T10,
                              INTL_MSR_UNITS T9,
                              EXMTN_TYPES T8,
                              COUNTRIES T7,
                              DCLTN_ITEMS T6,
                              MEASURE_UNITS T12
                              WHERE
                              h.PORT_CD21 = T6.PORT_CD AND
                              h.DCLTN_ISN2 = T6.DCLTN_ISN AND
                              T6.CTRY_CD = T7.CTRY_CD AND
                              T6.EXMTN_TYPE = T8.TYPE_CD (+) AND
                              T6.INTL_MSR_UNIT = T9.INTL_MSR_UNIT AND
                              T6.INV_MSR_UNIT  = T12.MSR_UNIT AND
                              T6.PORT_CD = T10.PORT_CD (+) AND
                              T6.INV_ISN = T10.INV_ISN (+) AND
                              T10.INV_CURCY_CD = T11.CURCY_CD (+)
                              ORDER BY  INV_SEQ,ITEM_SEQ1
                             ) ORDER BY ITEM_SEQ1, INV_SEQ)
            LOOP
                v_n := v_n + 1;
                dbms_lob.append (retVal, '<tr><td>' || CASE MOD (v_n, 5) WHEN 1 THEN 'أ' WHEN 2 THEN 'ب' WHEN 3 THEN 'ج' WHEN 4 THEN 'د' ELSE 'هـ' END || '</td><td>' || APEX_ESCAPE.HTML (CF_H_TARIFFFormula (i.FINAL_TARIFF_CD, i.ANAL_ITEM_CODE_1, i.ANAL_ITEM_CODE_2)) || '</td><td>' || APEX_ESCAPE.HTML (CF_2Formula (CF_H_TARIFFFormula (i.FINAL_TARIFF_CD, i.ANAL_ITEM_CODE_1, i.ANAL_ITEM_CODE_2), i.DCLTN_ISN1, i.ITEM_ISN, i.ANAL_ITEM_CODE_1, i.ANAL_ITEM_CODE_2, i.FINAL_TARIFF_CD, CF_NEW_ITEM_DESCFormula (i.FINAL_TARIFF_CD, h.DCLTN_DT, i.ITEM_DESC))) || '</td><td>' || APEX_ESCAPE.HTML (i.ORIGIN) || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (i.INV_COST, 'FM99999999990.00')) || '</td><td>' || APEX_ESCAPE.HTML (i.CURCY_INTL_CD) || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (CF_RATEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD, i.L_CUR_CURCY_CD), 'FM9990.00000')) || '</td><td>' || APEX_ESCAPE.HTML (CASE WHEN MOD ((i.CIF_COST) * 100, 100) = 0 THEN TO_CHAR (i.CIF_COST, 'FM99999999990') ELSE TO_CHAR (i.CIF_COST, 'FM99999999990.00') END) || '</td><td>' || APEX_ESCAPE.HTML (CF_D_RATEFormula (i.FINAL_TARIFF_CD, i.FINAL_TARIFF_DT, h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD, i.CTRY_CD, h.FINAL_CTRY_CD)) || '</td><td>' || APEX_ESCAPE.HTML (CF_DUTY_NAMEFormula (i.INCOME_TYPE)) || '</td><td>' || APEX_ESCAPE.HTML (CASE WHEN MOD ((CF_ITEM_TOTAL_DUTYFormula (i.ORGNL_DUTY, i.EXMTD_DUTY)) * 100, 100) = 0 THEN TO_CHAR (CF_ITEM_TOTAL_DUTYFormula (i.ORGNL_DUTY, i.EXMTD_DUTY), 'FM99999999990') ELSE TO_CHAR (CF_ITEM_TOTAL_DUTYFormula (i.ORGNL_DUTY, i.EXMTD_DUTY), 'FM99999999990.00') END) || ' ' || APEX_ESCAPE.HTML (CF_TEMPRORAYFormula (h.DCLTN_TYPE_CD, i.INCOME_TYPE, i.TEMP_ITEM)) || '</td></tr>');
            END LOOP;

            dbms_lob.append (retVal, '</tbody></table><table class="data" dir="rtl" style="border-collapse:collapse;width:100%;table-layout:fixed;margin-top:4px;"><thead><tr><th style="width:3%;font-size:9px;"></th><th style="width:12%;font-size:9px;">40 الجهة<br/>Agency</th><th style="width:9%;font-size:9px;">41 مرجع الفسح<br/>Relese Ref</th><th style="width:8%;font-size:9px;">32 الطرود الكمية<br/>.Qty</th><th style="width:7%;font-size:9px;">33 النوع<br/>Type</th><th style="width:8%;font-size:9px;">34 الصنف الكمية<br/>.Qty</th><th style="width:7%;font-size:9px;">35 وحدة<br/>Unit</th><th style="width:8%;font-size:9px;">36 الوزن الصافي<br/>Net</th><th style="width:8%;font-size:9px;">37 القائم<br/>Gross</th><th style="width:7%;font-size:9px;">42 الرمز<br/>Code</th><th style="width:12%;font-size:9px;">43 المصدر<br/>Sources</th><th style="width:11%;font-size:9px;">44 المستفيد<br/>Beneficiary</th></tr></thead><tbody>');
            v_n := 0;

            FOR i IN (SELECT * FROM (
                              SELECT
                              T11.CURCY_CD L_CUR_CURCY_CD,
                              T7.CTRY_CD L_CTRY_CTRY_CD1,
                              T6.FINAL_TARIFF_CD FINAL_TARIFF_CD,
                              T9.INTL_MSR_UNIT L_IMU_INTL_MSR_UNIT,
                              T8.TYPE_CD L_ET_TYPE_CD,
                              T6.EXMTN_TYPE EXMTN_CD,
                              T8.TYPE_NAME EXMTN_SRCE,
                              T6.PORT_CD PORT_CD1,
                              T10.PORT_CD PORT_CD3,
                              T10.INV_ISN INV_ISN2,
                              T6.ITEM_ISN ITEM_ISN,
                              T10.INV_SEQ INV_SEQ,
                              T6.ITEM_SEQ ITEM_SEQ1,
                              T6.DCLTN_ISN DCLTN_ISN1,
                              T10.INV_NBR INV_NBR,
                              T6.INV_ISN INV_ISN,
                              T10.INV_TYPE INV_TYPE,
                              T6.CTRY_CD CTRY_CD,
                              T10.DCLTN_ISN DCLTN_ISN3,
                              T10.INV_CURCY_CD DCLTN_INV_INV_CURCY_CD,
                              T6.FINAL_TARIFF_DT FINAL_TARIFF_DT,
                              T6.ITEM_DESC ITEM_DESC,
                              T7.CTRY_INTL_CD ORIGIN,
                              T6.INV_COST INV_COST,
                              T11.CURCY_INTL_CD CURCY_INTL_CD,
                              T6.CIF_COST CIF_COST,
                              T6.DUTY_TYPE INCOME_TYPE,
                              T6.INTL_MSR_UNIT INTL_MSR_UNIT,
                              T6.INTL_QTY INTL_QTY,
                              T9.IMSR_ARBC_NAME MSR_UNIT_NAME,
                              T6.NET_WT NET_WT,
                              T6.GROSS_WT GROSS_WT,
                              T6.ORGNL_DUTY ORGNL_DUTY,
                              T6.EXMTD_DUTY EXMTD_DUTY,
                              T6.TRF_UNIT_QTY TRF_UNIT_QTY,
                              T6.INV_QTY,
                              T6.INV_MSR_UNIT,
                              T12.MSR_ARBC_NAME,
                              T6.EXMTN_DECREE_PORT_CD,
                              T6.EXMTN_DECREE_ISN,
                              T6.EXMTN_ITEM_SEQ,
                              T6.EXMTN_ITEM_SUB_SEQ,
                              T6.TEMP_ITEM,
                              T6.ANAL_ITEM_CODE_1,
                              T6.ANAL_ITEM_CODE_2,
                              T10.INV_PMT_METHOD
                              FROM
                              CURRENCIES T11,
                              DCLTN_INVOICES T10,
                              INTL_MSR_UNITS T9,
                              EXMTN_TYPES T8,
                              COUNTRIES T7,
                              DCLTN_ITEMS T6,
                              MEASURE_UNITS T12
                              WHERE
                              h.PORT_CD21 = T6.PORT_CD AND
                              h.DCLTN_ISN2 = T6.DCLTN_ISN AND
                              T6.CTRY_CD = T7.CTRY_CD AND
                              T6.EXMTN_TYPE = T8.TYPE_CD (+) AND
                              T6.INTL_MSR_UNIT = T9.INTL_MSR_UNIT AND
                              T6.INV_MSR_UNIT  = T12.MSR_UNIT AND
                              T6.PORT_CD = T10.PORT_CD (+) AND
                              T6.INV_ISN = T10.INV_ISN (+) AND
                              T10.INV_CURCY_CD = T11.CURCY_CD (+)
                              ORDER BY  INV_SEQ,ITEM_SEQ1
                             ) ORDER BY ITEM_SEQ1, INV_SEQ)
            LOOP
                v_n := v_n + 1;
                v_l := NULL;
                FOR r IN (SELECT * FROM (
                                  SELECT
                                  /*
                                  T35.ATHRTY_CD L_RAC_ATHRTY_CD,
                                  T35.ATHRTY_SUB_CD L_RAC_ATHRTY_SUB_CD,
                                  --SUBSTR(T35.ATHRTY_ARBC_NM,1,15) SRCE_NAME,
                                  T34.RLSD_HDR_ISN L_RH_RLSD_HDR_ISN,
                                  T34.RAC_ATHRTY_CD L_RH_RAC_ATHRTY_CD,
                                  T34.RAC_ATHRTY_SUB_CD L_RH_RAC_ATHRTY_SUB_CD,
                                  T34.PORT_CD L_RH_PORT_CD,
                                  T33.RLSD_HDR_ISN L_RI_RLSD_HDR_ISN,
                                  T33.RLSD_ITM_SEQ L_RI_RLSD_ITM_SEQ,
                                  T32.RLS_SEQ RLS_SEQ,
                                  T32.RLSD_ITM_SEQ RLSD_ITM_SEQ,
                                  T33.PORT_CD L_RI_PORT_CD,
                                  */
                                  DISTINCT
                                  T32.PORT_CD PORT_CD8,
                                  T32.DCLTN_ITEM_ISN DCLTN_ITEM_ISN,
                                  T35.ATHRTY_ARBC_NM SRCE_NAME,
                                  T32.RLSD_HDR_ISN RELEASE_REF,
                                  RES_TYPE
                                  FROM
                                  RELEASE_AUTH_CODES T35,
                                  RLSD_HDRS T34,
                                  RLSD_ITEMS T33,
                                  RESTRCN_CNSMTNS T32
                                  WHERE
                                  i.PORT_CD1 = T32.PORT_CD AND
                                  i.ITEM_ISN = T32.DCLTN_ITEM_ISN AND
                                  T32.PORT_CD = T33.PORT_CD AND
                                  T32.RLSD_HDR_ISN = T33.RLSD_HDR_ISN AND
                                  T32.RLSD_ITM_SEQ = T33.RLSD_ITM_SEQ AND
                                  i.PORT_CD1 = T32.PORT_CD AND
                                  i.ITEM_ISN = T32.DCLTN_ITEM_ISN AND
                                  T33.PORT_CD = T34.PORT_CD AND
                                  T33.RLSD_HDR_ISN = T34.RLSD_HDR_ISN AND
                                  i.PORT_CD1 = T32.PORT_CD AND
                                  i.ITEM_ISN = T32.DCLTN_ITEM_ISN AND
                                  T34.RAC_ATHRTY_CD = T35.ATHRTY_CD AND
                                  T34.RAC_ATHRTY_SUB_CD = T35.ATHRTY_SUB_CD AND
                                  i.PORT_CD1 = T32.PORT_CD AND
                                  i.ITEM_ISN = T32.DCLTN_ITEM_ISN
                                  UNION
                                  SELECT
                                  DISTINCT
                                   res.port_cd,
                                  RES.DCLTN_ITEM_ISN,
                                  rel.athrty_arbc_nm,
                                  res.REQ_ISN,
                                  RES_TYPE
                                   FROM restrcn_cnsmtns res,
                                         ext_rstrct_rls_req_dtls ext,
                                         release_auth_codes rel
                                   WHERE (    (ext.issue_port_cd = res.port_cd)
                                          AND (ext.req_isn = res.req_isn)
                                          AND (ext.req_item_seq = res.req_item_seq)
                                          AND (rel.athrty_cd = ext.rac_athrty_cd)
                                          AND (rel.athrty_sub_cd = ext.rac_athrty_sub_cd)
                                         )
                                     ) ORDER BY SRCE_NAME, RELEASE_REF, RES_TYPE)
                LOOP
                    v_l := v_l || CASE WHEN v_l IS NOT NULL THEN '<br/>' END || APEX_ESCAPE.HTML (r.SRCE_NAME) || ' : ' || APEX_ESCAPE.HTML (CF_RES_TYPE_MEANFormula (r.RES_TYPE, r.RELEASE_REF));
                END LOOP;
                dbms_lob.append (retVal, '<tr><td>' || CASE MOD (v_n, 5) WHEN 1 THEN 'أ' WHEN 2 THEN 'ب' WHEN 3 THEN 'ج' WHEN 4 THEN 'د' ELSE 'هـ' END || '</td><td>' || v_l || '</td><td>' || '' || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (i.TRF_UNIT_QTY, 'FM99999999990.000')) || '</td><td>' || APEX_ESCAPE.HTML (CF_TRF_UNITFormula (i.FINAL_TARIFF_CD, i.FINAL_TARIFF_DT)) || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (i.INV_QTY, 'FM99999999990.00')) || '</td><td>' || APEX_ESCAPE.HTML (i.MSR_ARBC_NAME) || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (i.NET_WT, 'FM99999999990.000')) || '</td><td>' || APEX_ESCAPE.HTML (TO_CHAR (i.GROSS_WT, 'FM99999999990.000')) || '</td><td>' || CASE WHEN i.EXMTN_CD = 2 THEN APEX_ESCAPE.HTML (i.EXMTN_CD) || ' ع ص' ELSE APEX_ESCAPE.HTML (i.EXMTN_CD) END || '</td><td>' || CASE WHEN i.EXMTN_CD = 2 THEN APEX_ESCAPE.HTML (CF_EXMTN_DECREESFormula (i.EXMTN_DECREE_PORT_CD, i.EXMTN_DECREE_ISN)) ELSE APEX_ESCAPE.HTML (i.EXMTN_SRCE) END || '</td><td>' || CASE WHEN i.EXMTN_CD = 2 THEN APEX_ESCAPE.HTML (i.EXMTN_ITEM_SEQ) || CASE WHEN i.EXMTN_ITEM_SUB_SEQ IS NOT NULL THEN ' - ' END || APEX_ESCAPE.HTML (i.EXMTN_ITEM_SUB_SEQ) END || '</td></tr>');
            END LOOP;

            dbms_lob.append (retVal, '</tbody></table>');

            dbms_lob.append (retVal, '
              <table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="width:36%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;height:70px;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">45 المعاينة - أسباب عدم الفسح <span style="font-weight:normal;">Inspection - Reasons For Not Releasing</span></div>' || '<b style="color:#0e0f50;">التعهدات</b><br/>' || v_wvr || '<br/>' || APEX_ESCAPE.HTML (CF_OLD_IMPRTD_DCLTNFormula (h.DCLTN_TYPE_CD, h.IMPORT_DCLTN_ISN)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">46 المعاين <span style="font-weight:normal;">Inspector</span></div>' || APEX_ESCAPE.HTML (h.INSP_NAME) || CASE WHEN h.DCLTN_STATUS = 15 AND h.INSP_NAME IS NULL THEN APEX_ESCAPE.HTML (CF_GRP_NAMEFormula (h.DCLTN_ISN2, h.PMT_METHOD, h.DCLTN_TYPE_CD, h.GROUP_ID)) END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">47 رئيس المجموعة <span style="font-weight:normal;">Group Supervisor</span></div>' || APEX_ESCAPE.HTML (CF_GRP_NAMEFormula (h.DCLTN_ISN2, h.PMT_METHOD, h.DCLTN_TYPE_CD, h.GROUP_ID)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">48 ملاحظات أخرى <span style="font-weight:normal;">Other Remarks</span></div>' || '<b style="color:#0e0f50;">فواتير</b><br/>' || v_inv || '<br/><b style="color:#0e0f50;">مرفقات</b><br/>' || v_docs || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">49 تاريخ الفسح <span style="font-weight:normal;">Release Date</span></div>' || APEX_ESCAPE.HTML (TO_CHAR (h.GATE_DT, 'mi-mm-yyyy')) || '</td></tr></table></td><td style="width:30%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">38 المخلص الجمركي <span style="font-weight:normal;">Clearing Agent</span></div>' || APEX_ESCAPE.HTML (CF_BRKR_NAMEFormula (h.LIC_CATEGORY, h.DCLTN_DT, h.CHANGE_CATG_DATE, h.TRADE_NAME, h.BRKR_NAME)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">39 رقم الرخصة <span style="font-weight:normal;">.Licence No</span></div>' || APEX_ESCAPE.HTML (h.LIC_NBR) || '   ' || APEX_ESCAPE.HTML (CF_LIC_TYPEFormula (h.LIC_TYPE, h.LIC_NBR)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;">' || CASE WHEN NOT (h.DCLTN_TYPE_CD IN (1, 2)) THEN APEX_ESCAPE.HTML (CF_JORDANIAN_CARSFormula) END || CASE WHEN h.FINAL_CTRY_CD <> 100 AND (h.CL_VAL <> 0 AND h.CL_VAL IS NOT NULL) THEN '<br/><b style="color:#0e0f50;">القيمة</b> ' || APEX_ESCAPE.HTML (h.CL_VAL) || ' <b style="color:#0e0f50;">مؤمنة لخطاب ضمان مخلص</b><br/><b style="color:#0e0f50;">رقــم</b> ' || APEX_ESCAPE.HTML (h.CL_NBR) || ' <b style="color:#0e0f50;">بتاريخ</b> ' || TO_CHAR (h.CL_DT, 'mi-mm-yyyy') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">50 الترانزيت - خط السير <span style="font-weight:normal;">Transit - Route</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">51 جمرك الخروج <span style="font-weight:normal;">Exit Port</span></div>' || APEX_ESCAPE.HTML (CF_EXIT_PORT_NAMEFormula (h.EXIT_PORT_CD)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">52 قيد الخروج <span style="font-weight:normal;">.Exit Transaction No</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">53 تاريخه <span style="font-weight:normal;">Date</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">54 موظف الأمن <span style="font-weight:normal;">Security Officer</span></div>' || '' || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">55 مراقب الترانزيت <span style="font-weight:normal;">Transit Inspector</span></div>' || '' || '</td></tr></table></td><td style="width:34%;vertical-align:top;padding:0;"><table dir="rtl" style="width:100%;border-collapse:collapse;table-layout:fixed;"><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">56 الرسوم الجمركية <span style="font-weight:normal;">Total Duty - ريال SR</span></div>' || CASE WHEN MOD ((CF_TOTAL_DUTYFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) * 100, 100) = 0 THEN TO_CHAR (CF_TOTAL_DUTYFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990') ELSE TO_CHAR (CF_TOTAL_DUTYFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">56 A ضريبة القيمة المضافة <span style="font-weight:normal;">VAT</span></div>' || TO_CHAR (CALL_TOTAL_VATFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">56 B الضريبة الانتقائية <span style="font-weight:normal;">Excise</span></div>' || TO_CHAR (CALL_TOTAL_EXCISEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">57 رسوم المناولة <span style="font-weight:normal;">Handling</span></div>' || CASE WHEN MOD ((CF_HANDLINGFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) * 100, 100) = 0 THEN TO_CHAR (CF_HANDLINGFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990') ELSE TO_CHAR (CF_HANDLINGFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">58 رسوم الأرضيات <span style="font-weight:normal;">Storage</span></div>' || CASE WHEN MOD ((CF_STORAGEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) * 100, 100) = 0 THEN TO_CHAR (CF_STORAGEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990') ELSE TO_CHAR (CF_STORAGEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">59 رسوم أخرى <span style="font-weight:normal;">Other Charges</span></div>' || CASE WHEN MOD ((f_other) * 100, 100) = 0 THEN TO_CHAR (f_other, 'FM99999999990') ELSE TO_CHAR (f_other, 'FM99999999990.00') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">60 إجمالي الرسوم قطعي <span style="font-weight:normal;">TOTAL FEE - Definite</span></div>' || CASE WHEN MOD ((CF_TOTAL_FEE_DIFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) * 100, 100) = 0 THEN TO_CHAR (CF_TOTAL_FEE_DIFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990') ELSE TO_CHAR (CF_TOTAL_FEE_DIFINITFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') END || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">61 تأمين <span style="font-weight:normal;">Insured</span></div>' || CASE WHEN MOD ((CF_TOTAL_FEE_INSUREFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) * 100, 100) = 0 THEN TO_CHAR (CF_TOTAL_FEE_INSUREFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990') ELSE TO_CHAR (CF_TOTAL_FEE_INSUREFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD), 'FM99999999990.00') END || ' ' || APEX_ESCAPE.HTML (CF_GET_INSUE_NAMEFormula (h.DCLTN_NBR, h.DCLTN_DT, h.DCLTN_TYPE_CD)) || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">62 - 65 طريقة الدفع / رقم / تاريخ / بنك <span style="font-weight:normal;">Payment Method / .No / Date / Bank</span></div>' || APEX_ESCAPE.HTML (CF_METHOD_DESCFormula (h.COLL_ORDR_STA1, h.PMT_METHOD)) || CASE WHEN NVL (h.COLL_ORDR_STA1, 0) <> 7 THEN '<br/>' || APEX_ESCAPE.HTML (h.DOC_INS_NBR) || '   ' || APEX_ESCAPE.HTML (TO_CHAR (h.DOC_INS_DT, 'mi-mm-yyyy')) || '<br/>' || APEX_ESCAPE.HTML (CF_BANK_NAMEFormula (h.CO_BANK_CD)) END || '<br/>' || v_coll || '</td></tr><tr><td style="border:1px solid #a5a5a5;vertical-align:top;padding:2px 4px;font-size:10px;color:#707070;"><div style="color:#0e0f50;font-size:9px;font-weight:bold;margin-bottom:2px;">66 - 68 رقم إيصال الدفع / تاريخ / بنك <span style="font-weight:normal;">.Receipt No / Date / Bank</span></div>' || APEX_ESCAPE.HTML (CF_ATHRZ_RCPT1Formula (h.RCPT_TYPE22, h.ATM_AUTHRZTN_CD22, h.RCPT_NBR22)) || '<br/>' || APEX_ESCAPE.HTML (TO_CHAR (h.COLL_DT, 'mi-mm-yyyy')) || '<br/>' || APEX_ESCAPE.HTML (CF_BANK_BRNCH_NAMEFormula (h.CO_BANK_CD, h.CO_BANK_BRNCH_CD)) || '<br/>' || APEX_ESCAPE.HTML (CF_USER_NAMEFormula (h.CO_BANK_CD, h.CO_BANK_BRNCH_CD, h.COLL_DT, h.RCPT_NBR22, h.RCPT_TYPE22)) || '</td></tr></table></td></tr></table>');

            -- صفحة الملحق (M_96 لو CS_CAR > 4): أرقام شاسيهات السيارات
            IF cs_car > 4 THEN
                dbms_lob.append (retVal, '<div style="page-break-before: always"></div>
              <p style="text-align:center;font-size:13px;color:#0e0f50;font-weight:bold;">' || APEX_ESCAPE.HTML (v_port_name) || '</p>
              <p style="text-align:center;font-size:12px;color:#0e0f50;font-weight:bold;">' || APEX_ESCAPE.HTML (CF_1Formula (h.DCLTN_NBR, h.DCLTN_DT)) || '</p>
              <p style="font-size:11px;color:#707070;">' || v_rec || '</p>');
            END IF;
        END LOOP;

        dbms_lob.append (retVal, '
    </td>
  </tr>
</tbody>
</table>
<div id="MRD-Footer"><table border="0" cellpadding="1" cellspacing="1" style="width:100%"><tbody><tr><td></td></tr></tbody></table></div>
</div>
</div>
');
        RETURN retVal;
    END ARD_DCLN3100;
END DCLN3100_ARD;
/


